INSERT INTO m246_art VALUES
(0,0,$m246$الديباجة$m246$,$m246$قرار وزير الاستثمار رقم 108 لسنة 2016 بتاريخ 2016/12/15 بشأن إصدار اللائحة التنفيذية لقانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 .$m246$,'e8037055fae4810b735626b8461804c3'),
(1,-1,$m246$المادة الأولى إصدار$m246$,$m246$يعمل بأحكام اللائحة التنفيذية لقانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 المرفقة.$m246$,'0502fb612eaab702b6e26b85230428aa'),
(2,-1,$m246$المادة الثانية إصدار$m246$,$m246$ينشر هذا القرار واللائحة المرفقة في الوقائع المصرية، ويعمل بهما من اليوم التالي لتاريخ النشر.$m246$,'c6bea9c42be1f89e62b0dde152af015d'),
(1,0,$m246$المادة 1$m246$,$m246$مع عدم الإخلال بالتعريفات الواردة في قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 المشار إليه، يكون لكل من الكلمات والعبارات الآتية المعنى المبين قرين كل منها عند تطبيق أحكام هذه اللائحة والقرارات التنظيمية الصادرة تنفيذا للقانون المشار إليه، ما لم ينص على خلاف ذلك صراحة:
القانون: قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015
الوزير المختص: الوزير المختص بتطبيق أحكام القانون رقم 10 لسنة 2009
الهيئة: الهيئة العامة للرقابة المالية باعتبارها الجهة الإدارية المختصة بتطبيق القانون وهذه اللائحة.
المنقول الضامن: كل منقول مادي قائم أو مستقبلي، أو منقول معنوي قائم مملوك للمدين أو مقدم الضمان أو الدائن، يكون ضمانا لالتزام أو دين أو تمويل أو تسهيل ائتماني، ويجب على الدائن مراعاة توافر الضوابط التالية في المنقول الضامن عند قيامه بإشهار حق الضمان بالسجل:
1- أن يكون من المنقولات المسموح قانونا بتداولها وبيعها في مصر.
2- أن يكون في حيازة المدين أو مقدم الضمان.
3- أن يكون مما يمكن التنفيذ عليه مستقلا عن غيره، أخذا في الاعتبار الأحكام الخاصة بالمنقولات المثلية والعقارات بالتخصيص الواردة بالقانون وهذه اللائحة.
المنقول المستقبلي: المنقول المادي المتوقع وجوده مستقبلا في ملكية المدين أو مقدم الضمان أو الدائن طبقا للمجرى العادي للأمور، ويقصد بالمجرى العادي للأمور الحالات التي تقتضي وفقا لطبيعة العمل أو المجال الذي يستخدم فيه المنقول محل الضمان أن يترتب عليها وجود المنقول وتملكه في المستقبل وتشمل على سبيل المثال لا الحصر عمليات الشراء والإنتاج والاستيراد وزراعة وبذر المحاصيل الزراعية.
المنقولات المثلية: هي المنقولات التي يقوم بعضها مقام بعض عند الوفاء، والتي تقدر عادة في التعامل بين الناس بالعدد أو المقاس أو الكيل أو الوزن، وبمراعاة الصفات والنوع وجهة الصنع أو الإنتاج.
مقومات المحل التجاري: مجموعة الأموال المنقولة والمخصصة لمزاولة تجارة معينة والتي يجوز شهر حق الضمان عليها كلها أو بعضها وتتضمن السمعة التجارية، والاسم التجاري، والسمة التجارية، والعلامات التجارية وبراءات الاختراع، والرسوم، والنماذج الصناعية، وحقوق الملكية الأدبية والفنية، وتراخيص الاستغلال والبضائع والأثاث والآلات والأجهزة والمعدات وغيرها من المهمات اللازمة لاستغلال المحل التجاري.
الدائن: المضمون له من البنوك أو الجهات التي تمارس نشاط التمويل وغيرها من الجهات والأشخاص المانحة للتمويل أو الائتمان وتشمل:
1- الأشخاص الطبيعيين.
2- البنوك ومؤسسات التمويل المرخص لها بالعمل في مصر.
3- الشركات والجهات المرخص لها بممارسة نشاط التأجير التمويلي في مصر.
4- الجمعيات والمؤسسات الأهلية والشركات المرخص لها بممارسة نشاط التمويل متناهى الصغر في مصر.
5- الجهات المرخص لها بممارسة أنشطة متعلقة أو مرتبطة بتقديم تمويل أو ائتمان أو تقتضى طبيعة نشاطها المرخص لها به ذلك.
6- الأشخاص الاعتبارية والمنشآت الفردية المرخص لها بمزاولة أنشطة تجارة المنقولات التي يجوز قيد ضمان عليها وفقا للضوابط التي تحددها الهيئة.
7- الأشخاص الاعتبارية والأشخاص الطبيعيين مانحي رخص استخدام حقوق الملكية الفكرية.
المدين: الشخص الطبيعي أو الاعتباري الملتزم بالوفاء بالتزام أو دين مضمون.
مقدم الضمان: مالك المنقول الضامن، سواء المدين أو الغير.
الجهات المنصوص عليها بالمادة (13) من القانون: الجهات التي يخولها القانون صلاحية تحصيل حقوق الدولة أو غيرها من الحقوق المقررة قانونا بموجب الأحكام أو القرارات التي ترتب حقوقا على المنقولات.
طالب الإشهار: الشخص القائم بقيد الإشهار وتعديله وإلغائه والاعتراض عليه والبحث في السجل، سواء بالأصالة عن نفسه أو بالنيابة عن صاحب الحق المشهر.
الإشهار: قيد حق الضمان على الأموال المنقولة في السجل ويشمل ذلك الإشهار وتعديله والاعتراض عليه وإلغاءه.
السجل: سجل إشهار الضمانات المنقولة المنشأ وفقا لأحكام القانون.
المشغل: من يتولى إمساك وتشغيل سجل الضمانات المنقولة.
حق الضمان: الحق العيني التبعي الذي يقع على المنقول الضامن بموجب عقد الضمان المبرم بين الدائن والمدين أو مقدم الضمان لضمان الوفاء بالتزام أو دين.
عقد الضمان: العقد المبرم بين الدائن والمدين أو بين الدائن والمدين ومقدم الضمان والمثبت لحقوق الدائن على المنقول الضامن بالاسترشاد بالنموذج الذي تضعه الهيئة والذي يبين الشروط والأحكام الأساسية التي يجب أن يتضمنها العقد.$m246$,'301e1ee7a5ffbbb87448c02a5d14c252'),
(2,0,$m246$المادة 2$m246$,$m246$تسري أحكام القانون وهذه اللائحة على الحقوق المضمونة بمنقول في حيازة المدين أو مقدم الضمان يتفق أطراف عقد الضمان على إشهاره وفقا لأحكام هذا القانون وهذه اللائحة، على أن يكون المدين أو مقدم الضمان متمتعا بالأهلية، وأن يكون له حق إنشاء حق الضمان على المنقول الضامن، ويجب أن يكون محل إقامة أو المركز الرئيسي لأعمال المدين أو مقدم الضمان أو أحد فروع أي منهما التي تستفيد من التمويل يقع في جمهورية مصر العربية، بما في ذلك:
1- الحقوق المترتبة على بيع المنقول المشروط تأجيل نقل ملكيته لحين استيفاء الثمن.
2- الحقوق المترتبة على بيع المنقول المشروط استرداده أو إعادة شرائه عند إخلال المدين بالوفاء بالتزاماته.
3- الحقوق المترتبة على استخدام أو الترخيص باستخدام حقوق الملكية الفكرية.
وتسري أحكام القانون وهذه اللائحة المتعلقة بنفاذ حق الضمان في مواجهة الغير والأولوية والتنفيذ على المنقول الضامن على الحقوق الآتية:
1- حق الدائن في رهن الدين.
2- حق المؤجر بموجب عقود التأجير التمويلي أو التشغيلي الذي تزيد مدته على ستة أشهر.
3- حق مالك البضاعة برسم البيع.
4- حق الدائن في رهن المحل التجاري في حال قيامه بإشهاره وفقا لأحكام القانون.$m246$,'fbafb60c3f25de582896af22503ed4b4'),
(3,0,$m246$المادة 3$m246$,$m246$يجوز إنشاء حق ضمان على المنقول المادي القائم أو المستقبلي، وكذلك على المنقول المعنوي القائم المملوك للمدين أو مقدم الضمان أو الدائن والموجود في حيازة المدين أو مقدم الضمان.
ولا يجوز إنشاء حق ضمان على المنقولات الآتية:
1- المنقولات المملوكة للدولة أو لهيئات وجهات الوقف، أو المملوكة للسفارات الأجنبية والهيئات التي تتمتع بالحصانة.
2- الامتيازات والتراخيص الممنوحة من الدولة، أو الهيئات العامة، أو أحد الأشخاص الاعتبارية العامة.
3- المنقولات التي تملكها البنوك عدا تلك اللازمة لعملها وبغرض تمويل شرائها.
4- المنقولات المخصصة لأغراض شخصية أو منزلية إلا لتمويل شرائها.
5- المنقولات المملوكة على الشيوع ما لم يوافق جميع المالكين على إنشاء حق الضمان، وفي هذه الحالة يجب أن يتضمن عقد الضمان توقيع جميع المالكين على الشيوع أو من ينوب عنهم قانونا بالموافقة على إنشاء حق الضمان.$m246$,'c0a911078053f1d404eeff7116bf56e7'),
(4,0,$m246$المادة 4$m246$,$m246$لا تسري أحكام القانون وهذه اللائحة على الآتي:
1- الحقوق المترتبة على رهن الأوراق المالية المصرية أو الأجنبية أو شهادات الإيداع المقابلة لها سواء كانت مودعة بنظام الإيداع المركزي أم لم تكن مودعة.
2- الحقوق المترتبة على المنقول المستقبلي ويشمل كافة المبالغ والمنقولات التي من المتوقع أن يحصل عليها الشخص في الحالات التالية:
(أ) الميراث.
(ب) الوصية.
(جـ) المعاشات.
(د) وثائق التأمين على الحياة.
(هـ) التعويض بموجب اتفاق أو حكم.
(و) النفقة بموجب اتفاق أو حكم.
(ز) الأجور أو الرواتب ويقصد بها كل ما يتوقع أن يحصل عليه العامل مقابل عمله ثابتا كان أو متغيرا، نقدا أو عينا، بما في ذلك العمولة والنسبة المئوية والعلاوات أيا كان سبب استحقاقها أو نوعها والمزايا العينية والمنح والبدل ونصيب العامل في الأرباح والوهبة.$m246$,'45d9375a8c0747a6b84981b0c2f62a65'),
(5,0,$m246$المادة 5$m246$,$m246$تنشئ الهيئة سجلا مركزيا إلكترونيا لإشهار حقوق الضمان على المنقولات، ويتم إشهار الحقوق في هذا السجل، كما يتم قيد أي تعديل أو شطب أي قيد أو إلغاؤه وفقا للضوابط الواردة في القانون وهذه اللائحة.
وفي جميع الأحوال يكون تقديم الخدمة من خلال الموقع الإلكتروني للسجل على مدار 24 ساعة يوميا ولسبعة أيام في الأسبوع عدا فترات الصيانة والدعم الفني أو الحالات الطارئة وحالات القوة القاهرة.
ويلتزم مشغل السجل بتوفير الخدمة للجمهور للإجابة عن الاستفسارات وفقا للمواعيد التي تحددها الهيئة.$m246$,'d343855d9afca8d756e02a5033d6f5a8'),
(6,0,$m246$المادة 6$m246$,$m246$في حالة ما إذا عهدت الهيئة لإحدى الجهات أو الشركات المتخصصة بإنشاء وتشغيل السجل، يبقى إنشاء وتشغيل السجل خاضعا لإشراف ورقابة الهيئة وتكون الهيئة في جميع الأحوال هي المالكة لكافة البيانات والمعلومات المتاحة في السجل.
ويجب أن يتوافر في الجهة التي تعهد إليها الهيئة بإنشاء وتشغيل السجل على الأقل الشروط الآتية:
1- أن تكون ذات خبرة في مجالات إمساك السجلات أو الأنظمة الإلكترونية.
2- أن يكون لديها خبرة في مجال التطبيقات الرقمية من خلال استخدام التكنولوجيا.
3- أن يتوافر لدى القائمين على إدارتها الخبرات التكنولوجية والقانونية والإدارية اللازمة لإدارة وتشغيل السجل والتعامل مع طالبي الإشهار.
4- أن تتوافر لديها أنظمة تأمين البيانات والمعلومات وفقا للمعايير التي تحددها الهيئة.
5- أن تلتزم بالمواصفات الفنية لإنشاء وإدارة السجل وكذا أي تحديثات وتطويرات تطلبها الهيئة وخلال المدة التي تحددها.
6- أن تلتزم بإنشاء موقع إلكتروني على شبكة المعلومات الدولية، يمكن عن طريقه الاطلاع على البيانات المقيدة بالسجل، وذلك وفقا للمواصفات والضوابط التي تحددها الهيئة.
7- أن يكون لديها الملاءة المالية على الوفاء بالتزاماتها التعاقدية.
8- أن تبرم عقدا مع الهيئة ينظم حقوق والتزامات الجهة القائمة بإدارة السجل.
وتتولى الهيئة متابعة أعمال السجل والرقابة عليه ومتابعة شكاوى ومقترحات المتعاملين مع السجل وفحصها والبت فيها.$m246$,'e9bf430040531a8c5ddc390dc05cb464'),
(7,0,$m246$المادة 7$m246$,$m246$الغرض من السجل هو قيد/ حفظ البيانات المشهرة من الدائنين أو الجهات المنصوص عليها بالمادة (13) من القانون أو المحكوم لصالحهم والمصفين والمتعلقة بالحقوق على المنقولات وإتاحتها للكافة وفقا لقواعد الاستخدام ومحددات البحث طبقا لأحكام هذه اللائحة والقواعد التي تضعها الهيئة، ويتولى السجل ومشغله على الأخص ما يلي:
1- السماح لطالبي الإشهار بقيد الإشهارات وتقديم طلبات البحث وإجرائها إلكترونيا بصورة مباشرة عبر الإنترنت أو نظم التواصل الشبكي المباشر.
2- توفير إمكانية الحصول على خدمات السجل وبيان أسباب رفض الإشهار.
3- الإعلان عن وسائل الحصول على خدمات السجل وأيام وأوقات عمل أي من مكاتب السجل.
4- تدوين المعلومات الواردة في طلب الإشهار المقدم إلى السجل في قيود السجل، وإدراج تاريخ كل تسجيل ووقته.
5- تخصيص رقم قيد غير مكرر للإشهار.
6- فهرسة المعلومات الواردة في قيود السجل أو تنظيمها على نحو آخر، لجعلها قابلة للبحث.
7- صون سلامة المعلومات الواردة في قيود السجل.
8- تزويد طالب الإشهار بنسخة من الإشهار المقيد.
9- إزالة المعلومات الواردة في الإشهار المسجل من قيود السجل عند انقضاء المدة المحددة بالإشهار.
10- حفظ المعلومات الخاصة بالإشهارات الملغاة من قيود السجل.
11- إعداد برامج لتوعية الجمهور، وتعميم مواد ترويجية وإيضاحية، وتنظيم دورات تدريبية وإعداد تعليمات مفصلة بشأن ملء نماذج الإشهارات وتقديمها والبحث في قيود السجل، ضمانا لسلاسة إنشاء وتشغيل السجل والإقبال عليه.
12- ضمان أن تكون مواصفات المعدات والبرمجيات بالسجل ذات سمات تقلل إلى أدنى حد ممكن من احتمال تلف البيانات أو ارتكاب أخطاء تقنية أو حدوث خروقات أمنية، مع الالتزام بحفظ نسخ احتياطية من كافة بيانات السجل في مكان آخر آمن وفقا للمعايير التي تضعها الهيئة.$m246$,'e2330759c68de39da14ff466b8def7a0'),
(8,0,$m246$المادة 8$m246$,$m246$يقوم السجل بتقديم خدماته بمراعاة الضوابط الآتية:
1- تمكين مستخدمي السجل بشكل منتظم من فتح حساب لدى السجل لتيسير الانتفاع بالخدمات وتسديد أي مقابل ذي صلة.
2- المحافظة على أمن وسرية قاعدة بيانات السجل.
3- إمكانية قيام طالب الإشهار بإدخال تغييرات على البيانات التي يتم إشهارها.
4- إمكانية الحصول على تقارير عن المعاملات تتيح لطالبي الإشهار أن يتتبعوا معاملاتهم المقيدة في السجل على مدى فترة زمنية معينة.
5- إمكانية الحصول على نسخ من حقوق الضمان المشهرة والمقيدة في السجل ونتائج البحث.
6- إمكانية الحصول على تقارير إحصائية تتعلق بتشغيل السجل بما في ذلك البيانات الخاصة بحجم عمليات الإشهار والبحث ونفقات التشغيل أو مقابل الإشهار والبحث على مدى فترة زمنية معينة وغيرها من البيانات ذات الصلة بالقيد في السجل.
7- إمكانية إضافة خدمات أخرى لطالبي الإشهار والبحث وذلك بناء على طلب الهيئة أو بعد الحصول على موافقتها.$m246$,'adc599bd2dcac5917ac314ad74277c2d'),
(9,0,$m246$المادة 9$m246$,$m246$يكون للبيانات المشهرة بالسجل المتعلقة بوقت الإشهار وتاريخه المصدق عليها من السجل حجية المحررات الرسمية في الإثبات، ولا تكون للبيانات والمعلومات المشهرة بالسجل المتاحة على أي موقع إلكتروني آخر بخلاف الموقع الإلكتروني الخاص بالسجل أية حجية في الإثبات.$m246$,'7b063821246fb09fe09d6d3eee825ede'),
(10,0,$m246$المادة 10$m246$,$m246$يجوز لأي شخص البحث من خلال قواعد البيانات الخاصة في الموقع الإلكتروني للسجل. ولا يجوز إجراء البحث إلا عن طريق إدخال أحد المعايير الآتية:
1- رقم القيد غير المكرر للإشهار.
2- الرقم القومي للمدين/ مقدم الضمان إذا كان شخصا طبيعيا مصريا، أو رقم جواز سفره وبلد الإصدار حال كونه شخصا طبيعيا غير مصري، أو رقم تسجيله إذا كان شخصا معنويا، بحسب الأحوال.
وتقتصر المعلومات التي تظهر نتيجة البحث على ما يلي:
1- وجود إشهارات سارية مدرجة في السجل تحت رقم تسجيل غير مكرر أو تحت الرقم القومي للمدين/ مقدم الضمان أو رقم تسجيله، بحسب الأحوال.
2- رقم القيد غير المكرر لأي إشهار مدرج في السجل وتاريخه ووقته.
3- الرقم القومي/ رقم تسجيل المدين أو مقدم الضمان، بحسب الأحوال، واسم الدائن أو صاحب الحق المشهر بالسجل وعنوانه.
4- أي بيانات مدرجة في الإشهار فيما عدا تلك المعلومات المستخدمة لغايات إحصائية.
ولأي شخص قام بالبحث الحصول على نسخة من البيانات المدرجة في السجل تسمى ((تقرير البحث)) يصدر برقم تسجيل غير مكرر ويبين فيه البيانات الآتية:
1- وقت وتاريخ إجراء البحث.
2- المعيار المدخل من الشخص الذي أجرى البحث.
3- نتيجة البحث.
وتحفظ تقارير البحث في نظام السجل الإلكتروني ولكل ذي مصلحة بموجب إذن قضائي الحصول على نسخ ورقية معتمدة من نتائج البحث في السجل ويكون لها بعد تصديقها من السجل حجية في إثبات تاريخ الإشهار ووقته ومضمون ما طلب البحث عنه.$m246$,'de8a02d28b7fa8f37b1c48e84ba21363'),
(11,0,$m246$المادة 11$m246$,$m246$يجوز لأي شخص الحصول على صور معتمدة من البيانات المدرجة في السجل بعد إدراج بياناته على نموذج الطلب المعد لذلك من الهيئة وتسديد المقابل المقرر لذلك.
وتحفظ طلبات الحصول على صور معتمدة في نظام السجل الإلكتروني ويكون للصور المعتمدة من الهيئة حجية في إثبات تاريخ طلب الحصول على صورة معتمدة ووقته ومضمون نتيجة البحث.$m246$,'9e5b156c397f5877a3cfb132164e1b24'),
(12,0,$m246$المادة 12$m246$,$m246$تعتمد الهيئة دليلا يتضمن التعليمات الخاصة باستخدام السجل، والبيانات التي يتطلب السجل تقديمها لأغراض إحصائية.$m246$,'7cdf985882291ba86de75b048bb723e7'),
(13,0,$m246$المادة 13$m246$,$m246$يتم شهر حق الضمان من خلال قيام الدائن باستيفاء النموذج الإلكتروني المعد لهذا الغرض على أن يتضمن كافة المعلومات الأساسية التي يتضمنها عقد الضمان وعلى الأخص وصف المنقول الضامن وصفا عاما أو خاصا وبيان أطراف عقد الضمان وصفاتهم بالنسبة لهذا المنقول الضامن ومدة الضمان، وذلك مع مراعاة حكم المادة (21) من هذه اللائحة.
وفيما عدا إشهار الإلغاء وتقديم الاعتراض، يجب موافقة المدين/ مقدم الضمان على قيد أي إشهار في السجل عن طريق توقيع عقد الضمان أو أية وثيقة أخرى تفيد موافقته.
ويعتبر الدائن مخالفا لأحكام القانون وهذه اللائحة حالة قيامه بقيد أي إشهار دون الحصول على موافقة المدين/ مقدم الضمان الخطية المسبقة.
واستثناء من حكم الفقرة السابقة يجوز للجهات المنصوص عليها بالمادة (13) من القانون والمحكوم لصالحهم والمصفين تسجيل الإشهارات دون الحصول على موافقة المدين/ مقدم الضمان.$m246$,'129469f80ba2d06a05720ca69615dd8f'),
(14,0,$m246$المادة 14$m246$,$m246$مع مراعاة أحكام هذه اللائحة يتم قيد الإشهار في السجل بعد التأكد من استيفائه البيانات الآتية:
(أ) بيانات المدين/ مقدم الضمان، في حال كونه شخصا طبيعيا مصريا، فيتم إدخال رقمه القومي، وفي حال كونه شخصا طبيعيا غير مصري فيتم إدخال رقم جواز سفره وبلد الإصدار، وفي حالة الأشخاص المعنوية يتم إدخال رقم تسجيله أو إشهاره وفقا للقانون المنظم وفي جميع الأحوال يتم إدخال بيانات الاتصال الخاصة بالمدين/ مقدم الضمان.
(ب) بيانات طالب الإشهار، وفي حال كونه دائنا فيجب أن يتضمن اسمه ورقم تسجيله أو إشهاره وبيانات الاتصال الخاصة به، وفي حال الجهات المنصوص عليها بالمادة (13) من القانون فيتم إدخال اسم الجهة وشكلها القانوني وبيانات الاتصال الخاصة بها، وفي حال المحكوم لصالحه فإذا كان شخصا طبيعيا مصريا فيتم إدخال رقمه القومي، وفي حال كونه شخصا طبيعيا غير مصري فيتم إدخال رقم جواز سفره وبلد الإصدار، وفي حالة الأشخاص المعنوية يتم إدخال رقم تسجيله أو إشهاره وفقا للقانون المنظم وفي جميع الأحوال يتم إدخال بيانات الاتصال الخاصة به، وفي حال المصفي فيتم إدخال رقمه القومي وبيانات الاتصال الخاصة به.
(جـ) وصفا للمنقول موضوع الإشهار، ويجوز أن يكون الوصف عاما أو خاصا ما دام دالا على الموصوف، وفي حال كون المنقول الضامن أشياء مخصصة لأغراض الاستعمال الشخصية أو المنزلية فيجب أن يكون وصفها محددا.
وفي حال كون المنقول الضامن عقارا بالتخصيص فيجب إدخال البيانات المتعلقة بالعقار الذي خصص له حسبما هي واردة في سجلات الشهر العقاري.
(د) مدة سريان الإشهار.
(هـ) قيمة الالتزام المقرر على المنقول الضامن عند قيد الإشهار في السجل.
(و) البيانات الأخرى التي يطلبها السجل لاستخدامها لغايات إحصائية.$m246$,'7384822b985a32a991d7ed3c0ef9a9ea'),
(15,0,$m246$المادة 15$m246$,$m246$لا يقبل قيد أي إشهار في السجل بما في ذلك إشهارات الجهات المنصوص عليها بالمادة (13) والمحكوم لصالحهم والمصفين ما لم يكن مستوفيا للشروط والبيانات والإجراءات المحددة في القانون وهذه اللائحة وفقا للنموذج المعد من الهيئة.
وفي حالة استيفاء البيانات المطلوبة في السجل، تقبل عملية الإشهار ويتم إصدار تأكيد إلكتروني للتسجيل يتضمن تاريخ الإشهار ووقته ورقم القيد وكافة المعلومات المدرجة في عملية الإشهار، ولطالب الإشهار طباعة هذا التأكيد لاستخدامه في إثبات قيامه بتسجيل الإشهار.
ويصدر النظام الإلكتروني عند قيد كل إشهار رقما متسلسلا خاصا يستخدم لاحقا للتحقق من رقم الإشهار عند إدخاله في الإشهارات اللاحقة المتعلقة بذلك الإشهار.
ويحدد السجل مدى كفاية المعلومات المقدمة للإشهار وفقا لبرنامج تشغيله الإلكتروني وفي حال عدم كفايتها يظهر رسالة إلكترونية تحدد أسباب الرفض وما يلزم لاستكمالها.
ويعتبر الإشهار نافذا بمجرد قبول عملية الإشهار وظهور المعلومات الآتية في السجل:
1- تاريخ الإشهار ووقته.
2- رقم إشهار غير مكرر صادر عن السجل لكل إشهار.
3- البيانات المدرجة في الإشهار فيما عدا تلك البيانات المستخدمة لغايات إحصائية.
ومع عدم الإخلال بالحجية المقررة لتاريخ الشهر، لا يعتبر قبول تسجيل الإشهار دليلا على كفايته من الناحية القانونية، ولا دليلا على دقة المعلومات التي يتضمنها.
وللمحكمة أن تقرر عدم اعتبار الإشهار نافذا في حال وجود خطأ في بيانات المدين أو في بيانات المنقول الضامن يمنع من إظهار الإشهار عند إجراء عملية البحث.
وينحصر أثر حصول الخطأ في إدخال بيانات المنقول الضامن على نفاذ الإشهار بخصوص هذا المنقول، كما ينحصر أثر حصول الخطأ في بيانات المدين على نفاذ الإشهار بخصوص ذلك المدين.$m246$,'289fc693f6ec383ea2e993c36665c629'),
(16,0,$m246$المادة 16$m246$,$m246$يلتزم الدائن قبل القيام بعملية الإشهار بفتح حساب لدى مشغل السجل.
ويكون طالب الإشهار مسئولا عن صحة البيانات التي يضمنها في نموذج الإشهار، وفي حال قيامه بإدخال المعلومات مباشرة على الموقع الإلكتروني لا يكون السجل مسئولا عن صحة البيانات والمعلومات الواردة في الإشهار أو المستندات المرفقة به، ويكون الدائن مسئولا عن تعويض الأضرار التي قد تترتب للهيئة أو ذوي الشأن أو الغير الناشئة عن البيانات والمعلومات الخاطئة الواردة في الإشهار.
وفي الحالات المنصوص عليها بالمادة (21) من هذه اللائحة، يقوم السجل باستيفاء نموذج الإشهار بناء على نموذج ورقي مقدم من طالب الإشهار وموقع منه ويكون طالب الإشهار مسئولا عن دقة البيانات التي ضمنها في النموذج الورقي ويقوم السجل بتسجيل النموذج إلكترونيا فور وروده ويبقى السجل مسئولا عن تصحيح أي خطأ في إدخال البيانات في السجل الإلكتروني، ويقوم بتصحيح البيانات فور اكتشاف الخطأ عن طريق تسجيل إشهار معدل مع إرسال نسخة من الإشهار المعدل للدائن أو صاحب الحق المشهر بالسجل.$m246$,'7e97525f0aaa34e2368bcb845081fe92'),
(17,0,$m246$المادة 17$m246$,$m246$يكون الإشهار وأي تعديل عليه نافذا بمجرد ظهوره ضمن قواعد بيانات السجل وللمدة المحددة فيه.
وفي جميع الأحوال يتم إخطار المدين/ مقدم الضمان بالإشهارات المقيدة وفقا للوسائل والمواعيد التي تحددها الهيئة.$m246$,'be069b6a629e87bab27133a06a540c5f'),
(18,0,$m246$المادة 18$m246$,$m246$يجوز تعديل الإشهار المقيد عن طريق إشهار تعديل على أن يتضمن، بالإضافة للمعلومات المطلوبة لتسجيل الإشهار، ما يلي:
1- رقم القيد غير المكرر للإشهار.
2- اسم طالب الإشهار الذي يجري التعديل أو صاحب الحق المشهر بالسجل وصفته.
ويجوز مد مدة الإشهار المسجل قبل انتهاء مدته وذلك عن طريق تسجيل إشهار تعديل يتضمن في الخانة المخصصة مدة أخرى للسريان، وعند قبول إشهار التعديل بمد مدة السريان يعتبر الإشهار ممددا للمدة المحددة في إشهار التعديل والتي تبدأ من تاريخ انتهاء المدة التي تم مدها.
وعدا الحالات التي يكون فيها التعديل لمصلحة المدين/ مقدم الضمان فإذا كان موضوع الإشهار المعدل إضافة منقول ضامن أو مدين أو مقدم ضمان أو تمديد سريان الإشهار أو زيادة قيمة الالتزام المضمون، فيجب الموافقة عليه من المدين/ مقدم الضمان.
وفي جميع الأحوال تكون مرتبة حقوق الدائن عند التعديل بزيادة الالتزامات أو مدة الضمان أو إضافة منقولات أخرى أو استبدالها من تاريخ إشهار التعديل فيما يتعلق بهذه التعديلات.$m246$,'d1c552c65b7ed96e9e77657a11eae54a'),
(19,0,$m246$المادة 19$m246$,$m246$يكون لأي شخص تم إدراج اسمه كمدين/ مقدم الضمان أو محكوم عليه في أي إشهار أن يتقدم باعتراض إلى السجل على الإشهار أو أي من البيانات الواردة به على أن يتضمن الاعتراض ما يلي:
1- اسم المعترض.
2- رقم القيد للإشهار المعترض عليه.
3- بيان أسس الاعتراض، بما في ذلك الادعاء بعدم صحة الإشهار أو عدم دقة المعلومات الواردة فيه.
4- أي بيانات أخرى يطلبها المشغل.
ويقوم السجل بإخطار الدائن بالاعتراض إلكترونيا والرد على مقدم الاعتراض خلال أسبوع من تاريخ تقديمه بما انتهت إليه الإجراءات.
وفي جميع الأحوال، يجوز لكل ذي مصلحة الاعتراض لدى قاضي الأمور المستعجلة على ما يرد من إشهار لحقوق الضمان بالسجل، دون أن يؤثر هذا الاعتراض على نفاذ حق الضمان في مواجهته أو مواجهة الغير.$m246$,'3c283e089005a4eb4f05d829f6f92fd6'),
(20,0,$m246$المادة 20$m246$,$m246$في الأحوال التي ينقضي فيها حق الضمان قبل انتهاء مدة الإشهار بالسجل، سواء بسبب عدم موافقة المدين أو مقدم الضمان على تسجيل الإشهار أو الإبراء أو الأداء أو لأي سبب آخر يلتزم الدائن أو غيره من أصحاب الحقوق المشهرة بالسجل بإلغاء الإشهار خلال عشرة أيام على الأكثر من تاريخ تحقق الواقعة المنشئة لانقضاء حق الضمان.
ويستوفي الدائن أو غيره من أصحاب الحقوق المشهرة بالسجل النموذج الإلكتروني للإلغاء والمعد لهذا الغرض بالسجل والذي يجب أن يتضمن:
1- رقم القيد غير المكرر للإشهار.
2- اسم طالب الإشهار الذي يجري الإلغاء أو صاحب الحق المشهر بالسجل وصفته.
3- إقرار بأن الإشهار المطلوب إلغاؤه أصبح غير نافذ في مواجهة الدائن أو صاحب الحق المشهر بالسجل طالب الإلغاء، وكذا غير نافذ في مواجهة المدين/ مقدم الضمان والغير.
ويستمر عرض الإشهار الملغي (مع بيان أنه قد ألغى) ضمن قواعد بيانات السجل إلى حين انقضاء مدته.
ولا يسري الإلغاء في مواجهة أي دائن تم إشهار حقوقه على ذات المنقول الضامن في ذات العقد ما لم يوافق على الإلغاء.
وفي حالة عدم قيام الدائن أو غيره من أصحاب الحقوق المشهرة بالسجل بإلغاء الإشهار خلال المدة المحددة أعلاه، فللمدين أو مقدم الضمان أو كل ذي صفة أو مصلحة أن يقدم عريضة بذلك لقاضي الأمور المستعجلة لإصدار أمر بإلغاء القيد موضحا به سبب انقضاء حق الضمان، ويصدر قاضي الأمور المستعجلة أمرا بإلغاء الإشهار خلال يومي عمل على الأكثر من تاريخ تقديم الطلب ويتولى السجل إلغاء الإشهار في قيوده لدى استلام نسخة رسمية من الأمر الصادر عن قاضي الأمور المستعجلة بالإلغاء.$m246$,'ac12b2a49dc2b2346afb4ad9a04223e8'),
(21,0,$m246$المادة 21$m246$,$m246$يجب على المحكمة المختصة بناء على طلب كتابي من المحكوم لصالحه، التصريح له بشهر الحقوق المترتبة على منقولات المدين في الحالتين التاليتين:
1- صدور حكم وقتي نهائي بتوقيع حجز تحفظي على هذه المنقولات.
2- صدور حكم وقتي نهائي بالتنفيذ على هذه المنقولات.
وفي حال اتفاق الشركاء/ المساهمين بتصفية الشركة اختياريا يقوم المصفي المعين من قبل الشركاء/ المساهمين بإشهار قرار التصفية الاختيارية، كما يلتزم المصفي بإشهار التصفية الإجبارية بالسجل.
وفي الحالات المشار إليها بالفقرتين السابقتين يقوم المحكوم لصالحه أو المصفي بحسب الأحوال بتعبئة نموذج الإشهار بناء على نموذج ورقي مقدم من طالب الإشهار وموقع منه ومرفقا به صورة موثقة من القرار أو الحكم، ويكون طالب الإشهار مسئولا عن دقة البيانات التي ضمنها في النموذج الورقي ويقوم مشغل السجل بتسجيل النموذج إلكترونيا فور وروده، شريطة تحميل صورة إلكترونية من الحكم أو القرار المطلوب إشهاره على قاعدة بيانات السجل وذلك بمراعاة الفقرة الثانية من المادة (16) من هذه اللائحة.
وتقوم المحكمة التي أصدرت حكما بإشهار الإفلاس بإصدار أمر للسجل لإشهار ذلك الحكم ويقوم السجل بتسجيل النموذج إلكترونيا فور وروده وتحميل صورة إلكترونية من الحكم المطلوب إشهاره على قاعدة بيانات السجل وذلك بمراعاة الفقرة الثانية من المادة (16) من هذه اللائحة.
وعلى الجهات المنصوص عليها بالمادة (13) من القانون إشهار الأحكام أو القرارات التي ترتب حقوقا على المنقولات مباشرة من خلال الموقع الإلكتروني للسجل عن طريق استيفاء النموذج المعتمد من الهيئة شريطة تحميل صورة إلكترونية من الحكم أو القرار المطلوب إشهاره على قاعدة بيانات السجل.
وتعفي عمليات الإشهار المنصوص عليها في هذه المادة من الرسوم المنصوص عليها في هذه اللائحة.$m246$,'488903cd45995e8f65d5a44dd052af63'),
(22,0,$m246$المادة 22$m246$,$m246$يلزم لإشهار الحقوق الواردة بهذا الفصل مراعاة أحكام المواد (1) 6)، (15)، (14)، (13 بالإضافة للإجراءات الواردة بهذا الفصل.$m246$,'2daab5be7a89040f26975463fbe5488d'),
(23,0,$m246$المادة 23$m246$,$m246$ملغاة$m246$,'e92ebe02473ae540e86780a17ab84d1b'),
(24,0,$m246$المادة 24$m246$,$m246$يجوز للدائن المرتهن حيازيا إشهار رهنه في السجل عن طريق استيفاء النموذج الإلكتروني المعد من الهيئة لهذا الغرض، على ألا يخل ذلك بنفاذ حقه على المال المرهون في مواجهة الغير وفقا لأحكام القانون المدني.
ويترتب على إشهار الرهن الحيازي وفقا لأحكام القانون وهذه اللائحة قيام الدائن المرتهن حيازيا بنقل حيازة المنقول الضامن إلى المدين أو مقدم الضمان بحسب الأحوال.
ويمنح إشهار الرهن الحيازي الدائن المرتهن الحقوق التي يتمتع بها كما لو كان حائزا للمال المرهون بما في ذلك حق تتبعه في يد حائزه وتقدم الدائنين الآخرين في استيفاء الدين من حصيلة بيع المرهون عند التنفيذ عليه وفقا لأحكام القانون.$m246$,'a25af077a4c5f69d0db4ad65493d02ee'),
(25,0,$m246$المادة 25$m246$,$m246$يتم شهر حقوق الضمان على مقومات المحل التجاري بالسجل من خلال قيام الدائن باستيفاء النموذج الإلكتروني الخاص بذلك على أن يرفق به إلكترونيا مستخرج رسمي حديث لا يزيد تاريخ إصداره على شهر من السجل التجاري ببيانات الرهون المثبتة عليه وغيره من الحقوق المشهرة وآجالها وقيمة الالتزام المشهر بالسجل وبيانات الدائن.
ويقوم السجل بإخطار السجل التجاري بكافة الإشهارات التي تمت بالسجل على مقومات المحل التجاري أو أي تعديل أو إلغاء لها على أن يكون الإخطار إلكترونيا كلما كان ذلك ممكنا.
ويلتزم الدائن بإخطار السجل والسجل التجاري فور البدء في إجراءات التنفيذ على مقومات المحل التجاري.
وفي حال قيام الدائن بإلغاء الإشهار بالسجل يلتزم الدائن باستيفاء النموذج الإلكتروني الخاص بذلك على أن يرفق به إلكترونيا شهادة حديثة من السجل التجاري بشطب الرهن من السجل التجاري.$m246$,'b6a179508bba41a8f191daaf298536a9'),
(26,0,$m246$المادة 26$m246$,$m246$يتم شهر حقوق الضمان على حقوق الملكية الفكرية بالسجل من خلال قيام الدائن باستيفاء النموذج الإلكتروني الخاص بذلك.
على أن يرفق به إلكترونيا مستخرج رسمي حديث لا يزيد تاريخ إصداره على شهر من الجهة القائمة على رهن حقوق الملكية الفكرية وفقا للقانون رقم 82 لسنة 2002 والموجه للسجل بتاريخ قيد هذه الحقوق ومدى وجود رهون عليها وآجالها وقيمة الالتزام المشهر وبيانات الدائن.
ويقوم السجل بإخطار الجهة القائمة على رهن حقوق الملكية الفكرية إلكترونيا بشكل أسبوعي بكافة الإشهارات التي تمت بالسجل على حقوق الملكية الفكرية أو أي تعديل أو إلغاء لها.
ويلتزم الدائن بإخطار السجل والجهة القائمة على رهن حقوق الملكية الفكرية فور البدء في إجراءات التنفيذ على حقوق الملكية الفكرية.
وفي حال قيام الدائن بإلغاء القيد بالسجل يلتزم الدائن باستيفاء النموذج الإلكتروني الخاص بذلك على أن يرفق به إلكترونيا شهادة حديثة من الجهة القائمة على رهن حقوق الملكية الفكرية بشطب الرهن لديها.$m246$,'17b375c2423eb6d966ff65d197adb608'),
(27,0,$m246$المادة 27$m246$,$m246$يجوز للدائن أو لأصحاب الحقوق المقررة بموجب المادة (13) من القانون شهر الحقوق المنشأة لصالحهم على المنقولات قبل العمل بأحكام هذا القانون والسارية في تاريخ العمل به وفقا للقوانين المنظمة لها.
والتي كانت ستخضع له فيما لو كان القانون ساريا عند إبرامها، وذلك وفقا لأحكام القانون وهذه اللائحة.
ويتولى المشغل الإعلان عن مواعيد قيام الدائنين بإشهار حقوقهم طبقا للمادة الرابعة من مواد إصدار القانون. وعلى الدائنين الالتزام بهذه المواعيد.$m246$,'d7cfc9eaefd431afa1426810c6ae0760'),
(28,0,$m246$المادة 28$m246$,$m246$يستحق مقابل عن إشهار الحقوق بالسجل أو تعديله أو الاطلاع على البيانات المشهرة وفقا للجدولين الملحقين بهذه اللائحة.
وتكون مصروفات الإشهار وتجديده وتعديله على الدائن ما لم يتفق على خلاف ذلك، ويعفي إلغاء الإشهار وشطبه من أي رسوم أو مصروفات.
وتحدد الهيئة وسائل سداد هذا المقابل.$m246$,'508afe091812bf3b4281206cfd10d1d2'),
(30,0,$m246$المادة 30$m246$,$m246$يجوز للدائن التنازل عن حق الضمان المشهر إلى شخص آخر ويسري هذا التنازل في حق الغير من تاريخ إشهاره بالسجل، ولا يسري التنازل في حق المدين أو مقدم الضمان إلا من تاريخ إخطارهما به بالطريقة المحددة في عقد الضمان.
ويقوم الدائن بإشهار التنازل عن حق الضمان باستيفاء النموذج الإلكتروني المعد لهذا الغرض بالسجل، على أن يتضمن التنازل عن الحق البيانات الخاصة بالمتنازل إليه.
ويكون للمتنازل إليه ذات حقوق ومرتبة الدائن المتنازل.$m246$,'23d8de5e106e20c86c030fb706729bc0'),
(31,0,$m246$المادة 31$m246$,$m246$يجوز للدائن التنازل كتابة عن مرتبة الأولوية لحق الضمان المقرر له وفقا لأحكام هذا القانون في حدود الدين المتنازل عنه المضمون بهذا الحق، ويكون هذا التنازل نافذا في مواجهة الغير من تاريخ إشهار هذا التنازل بالسجل.
ويقوم الدائن بإشهار التنازل عن مرتبة الأولوية لحق الضمان المقرر له باستيفاء النموذج الإلكتروني المعد لهذا الغرض بالسجل، ويجب أن يتضمن التنازل البيانات الخاصة بالمتنازل إليه، ويكون للمتنازل إليه ذات حقوق ومرتبة الدائن المتنازل في حدود دين المتنازل.$m246$,'a7107ceeebf371860b85e2bb3bed42d4'),
(32,0,$m246$المادة 32$m246$,$m246$يجوز إنشاء حق ضمان على العقار بالتخصيص شريطة إمكانية فصله عن العقار دون أن ينشأ عن ذلك ضرر لأي منها.
تحدد مرتبة الضمان في هذه الحالة من تاريخ إشهاره في السجل وفقا للإجراءات المحددة في القانون وهذه اللائحة لإشهار حق الضمان وتسجيله في صحيفة العقار قبل توثيق أي حقوق أخرى على العقار، ويتقدم هذا الحق على الحقوق العينية الأخرى الواقعة على العقار بشرط التأشير بتسجيل حق الضمان في صحيفة الشهر العقاري إذا كان العقار مسجلا.
وإذا أصبح المنقول الضامن عقارا بالتخصيص يستمر نفاذ حق الضمان في مواجهة الغير ويتقدم الحقوق العينية الأخرى الواقعة على العقار بشرط التأشير بتسجيل حق الضمان في صحيفة الشهر العقاري إذا كان العقار مسجلا.
وإذا كان العقار غير مسجل، تحدد مرتبة الأولوية لحق الضمان على العقار بالتخصيص من تاريخ إشهاره في السجل.$m246$,'21cbb2e9e7c1653ab3e9f4487480c651'),
(33,0,$m246$المادة 33$m246$,$m246$إذا حصل المدين على تمويل لشراء منقولات تشكل في الأحوال العادية جزءا من منقولات سبق إنشاء حقوق ضمان عليها، يكون لممول شراء المنقولات الإضافية أولوية في استيفاء حقوقه منها وفقا للشروط الآتية:
1- قيام الدائن باستيفاء إجراءات الإشهار بالسجل خلال مدة لا تجاوز ثلاثة أيام عمل من تاريخ حيازتها.
2- قيام الدائن بإخطار الدائنين الآخرين المقيدة حقوقهم على المنقول وفقا لبيانات الاتصال الخاصة بهم في البيانات المقيدة في السجل.$m246$,'2a3de09933415b2942c206c119834722'),
(34,0,$m246$المادة 34$m246$,$m246$في حالة إنشاء حق ضمان على منقولات مثلية فيستمر نفاذ حق الضمان إذا اختلطت تلك المنقولات بمثيلاتها، وفي هذه الحالة تتساوى حقوق الضمان النافذة تجاه الغير على مجموع المنقولات المثلية في المرتبة، ويتحدد حق كل دائن بنسبة دينه المضمون لإجمالي المنقولات المختلطة اعتبارا من تاريخ الاختلاط.$m246$,'ae02e2fbaca03496769884574067af5a'),
(35,0,$m246$المادة 35$m246$,$m246$في حال إنشاء حق ضمان على منقولات تدخل ضمن مكونات إنتاج سلعة أو منتج، فيجب لسريان الإشهار أن تتضمن بيانات الإشهار ما ستؤول إليه هذه المنقولات من سلع أو منتج نهائي متضمنة عددها و/أو كميتها ونسبة حق الضمان لإجمالي قيمة هذه السلع أو المنتجات.
وفي حال وجود حقوق ضمان مشهرة على أكثر من منقول ضمن مكونات إنتاج السلعة أو المنتج النهائي وتضمين بيانات الإشهار ما ستؤول إليه هذه المنقولات من سلع أو منتج نهائي، فتسري حقوق الضمان المشهرة للدائنين على عدد و/أو كمية السلعة أو المنتج النهائي وتتساوى جميع حقوق الضمان المشهرة في الأولوية كل بنسبة حق ضمانه لإجمالي قيمة السلعة أو المنتج.$m246$,'71e68d6841389a80a36f188ee4c113b9'),
(36,0,$m246$المادة 36$m246$,$m246$إذا منح عقد الضمان الدائن الحق ببيع المنقول الضامن إذا لم يقم المدين بتنفيذ التزاماته أو بتسديد الدين المضمون أو الأقساط في المواعيد ووفقا للشروط المتفق عليها في العقد، يكون المنقول الضامن قابلا للتنفيذ عليه إذا تخلف المدين عن تنفيذ التزاماته بموجب عقد الضمان، وفي هذه الحالة يكون للدائن القيام بما يلي:
1- حيازة المال المنقول الضامن بشكل مباشر أو غير مباشر.
2- التصرف في المنقول الضامن.
3- ممارسة أي من الحقوق الواردة في عقد الضمان أو في القانون أو أي قانون آخر.
ولا يجوز للدائن البدء في إجراءات البيع إلا بعد مضي خمسة أيام من تكليف المدين بالوفاء بموجب كتاب مسجل مصحوب بعلم الوصول، وكذلك إخطار الدائنين المشهرة حقوقهم المضمونة على المنقول الضامن بذلك بموجب كتاب مصحوب بعلم الوصول على عناوينهم المشهرة قبل البدء في إجراءات البيع بخمسة أيام على الأقل.
وعلى الدائن الالتزام بالإجراءات التي تضمنها عقد الضمان المنظمة لعملية البيع وتوزيع حصيلته ويجب على المدين تمكينه من حيازة المنقول الضامن، فإذا امتنع عن ذلك كان للدائن أن يطلب بناء على عريضة تقدم إلى القاضي المختص بالمحكمة الاقتصادية التي يقع في دائرتها موطن المدين؛ الأمر بتسليمه المنقول الضامن، ويصدر القاضي أمر التسليم خلال ثلاثة أيام عمل على الأكثر من تاريخ تقديم الطلب إليه ويتم تنفيذ الأمر بالطرق الجبرية المقررة قانونا.$m246$,'ca128292a246e4595894e7c398fca92f'),
(37,0,$m246$المادة 37$m246$,$m246$إذا لم يتضمن عقد الضمان حق الدائن في اتخاذ إجراءات البيع مباشرة في حالة إخلال المدين بالتزاماته، كان للدائن بعد انقضاء خمسة أيام من تاريخ تكليف المدين بالوفاء أن يطلب بناء على عريضة تقدم إلى القاضي المختص بالمحكمة الاقتصادية التي يقع في دائرتها موطن المدين؛ الأمر ببيع المنقول الضامن كله أو بعضه.
ولا يجوز تنفيذ الأمر الصادر عن القاضي ببيع المنقول الضامن إلا بعد انقضاء خمسة أيام من تاريخ إخطاره إلى المدين بموجب كتاب مصحوب بعلم الوصول وإخطار الدائنين المشهرة حقوقهم المضمونة بموجب كتاب مصحوب بعلم الوصول قبل التنفيذ بخمسة أيام على الأقل مع بيان المكان الذي يجري فيه البيع وتاريخه وساعته، ويجري البيع في الزمان والمكان اللذين عينهما القاضي وبالطريقة التي يحددها بما يتناسب مع طبيعة المنقول الضامن.$m246$,'b7d2d3c8b6cc948d9a6a1d81b548c7a1'),
(38,0,$m246$المادة 38$m246$,$m246$للدائن بيع المنقول الضامن دون اتباع الإجراءات والمدد الواردة بالمادتين السابقتين في أي من الحالات الآتية:
1- عدم وجود حقوق مضمونة لدائنين آخرين على ذات المنقول الضامن وموافقة المدين على البيع.
2- الحالات التي تقل فيها المدة المقررة لصلاحية المنقول الضامن عن مجموع المدد اللازمة لتكليف المدين بالوفاء وإخطار الدائنين الآخرين المشهرة حقوقهم على هذا المنقول وإنهاء بيع المنقول الضامن وتسليمه للمشتري وفقا للإجراءات المحددة بالقانون وهذه اللائحة، وبشرط قيام الدائن بإخطار مقدم الضمان والدائنين الآخرين المشهرة حقوقهم بالسجل -حال وجودهم -بوقت البيع ومكانه ومقدار الدين الذي يجري البيع لسداده وذلك بموجب خطاب مسجل مصحوب بعلم الوصول قبل البدء في البيع بيوم عمل على الأقل.
3- الحالات التي تقل فيها القيمة التقديرية للمنقول الضامن عن عشرة آلاف جنيه، وبشرط قيام الدائن بإخطار مقدم الضمان والدائنين الآخرين المشهرة حقوقهم بالسجل -حال وجودهم -بوقت البيع ومكانه ومقدار الدين الذي يجري البيع لسداده وذلك بموجب خطاب مسجل مصحوب بعلم الوصول قبل البدء في البيع بثلاثة أيام عمل على الأقل.
ويجب على الدائن أن يبذل في ذلك العناية التي يبذلها في أعماله الخاصة، ويكون الدائن مسئولا عن تعويض مقدم الضمان والمدين وأي من أصحاب الحقوق الأخرى على المال الضامن عن الأضرار الناتجة عن مخالفته لإجراءات التنفيذ المبينة في هذه اللائحة.
وفي جميع الأحوال، يترتب على بيع المنقول الضامن تطهير المنقول الضامن من كافة الديون وتنتقل حقوق الدائنين إلى الثمن.$m246$,'e39f71d377cda507efa7bc9e89d76cb2'),
(39,0,$m246$المادة 39$m246$,$m246$يجب أن يلصق على باب المكان الموجودة به المنقولات محل البيع وفي اللوحة المعدة لذلك بالمحكمة المختصة إعلانات يبين فيها يوم البيع وساعته ونوع الأشياء محل البيع ووصفها بالإجمال.
وإذا تضمن عقد الضمان أن يتم النشر في الصحف عند اتخاذ إجراءات البيع فيجب الإعلان عن البيع بالنشر في إحدى الصحف اليومية، ويذكر في الإعلان يوم البيع وساعته ومكانه ونوع المنقولات محل البيع ووصفها بالإجمال، وإذا لم يتضمن عقد الضمان اتفاقا على النشر في الصحف، يجوز للدائن أو المدين أو مقدم الضمان أن يطلب من المحكمة المختصة النشر على نفقته الخاصة.
وإذا تضمن عقد الضمان حق الدائن بيع المنقول الضامن فيجري البيع في المكان الذي توجد فيه المنقولات، وإذا لم يتضمن عقد الضمان ذلك فيجري البيع في الزمان والمكان اللذين عينهما القاضي بما يتناسب مع طبيعة المنقول.
ويتم البيع بالمزاد العلني بالمناداة بشرط دفع الثمن فورا، ويجب عدم البدء في البيع إلا بعد أن يتم جرد المنقولات محل البيع وتحرير محضر بذلك.
ويشتمل محضر البيع على ذكر جميع إجراءات البيع وما تم من الاعتراضات والعقبات وما اتخذ في شأنها وحضور الدائن أو مقدم الضمان أو غيابه والثمن الذي رسا به المزاد وعلى اسم من رسا عليه وتوقيعه.
وإذا لم يدفع المشتري الثمن فورا وجبت إعادة البيع وفقا للإجراءات السابقة.
ويكون للمدين ومقدم الضمان وأي من أصحاب الحقوق الأخرى على المنقول أن يتقدم لقاضي الأمور المستعجلة بالمحكمة المختصة لإيقاف إجراءات البيع قبل يوم عمل على الأقل من التاريخ المحدد لبيع المنقول على أن يرفق بالطلب ما يفيد إيداع خزينة المحكمة ما يكفي لسداد حقوق الدائنين المشهرة بالسجل أو المتبقي منها بحسب الأحوال بالإضافة إلى جميع المصاريف والنفقات، ويترتب على قبول الطلب وقف إجراءات البيع
ويتم سداد حقوق الدائنين بحسب ترتيبها وكذلك مصاريف ونفقات التنفيذ من المبالغ المودعة خزينة المحكمة.
ولقاضي التنفيذ بناء على طلب المدين أو مقدم الضمان أو أي من أصحاب الحقوق الأخرى على المنقول الضامن أن يعدل في إجراءات التنفيذ في أية مرحلة من مراحلها بالشكل الذي يراه مناسبا إذا تبين وقوع مخالفة لإجراءات التنفيذ على المنقول الضامن والمنصوص عليها في القانون وهذه اللائحة.$m246$,'26a1d3f70d57a4d7d92c727cad4a6863'),
(40,0,$m246$المادة 40$m246$,$m246$يجب مراعاة الإجراءات الآتية في حالة بيع المنقول الضامن من الدائن:
1- أن يودع حصيلة البيع خزينة المحكمة الاقتصادية المختصة الواقع في دائرتها موطن المدين.
2- أن يسلم قلم كتاب المحكمة بيانا بالحقوق على المنقول الضامن المشهرة في السجل كما هي في اليوم السابق بتاريخ إيداع حصيلة البيع.$m246$,'432aebe76254bab96e0d553c3bf7172e'),
(41,0,$m246$المادة 41$m246$,$m246$يأمر القاضي المختص بالمحكمة الاقتصادية بإعداد قائمة توزيع مؤقتة للعوائد وحصيلة التنفيذ وفقا للأولويات المحددة في المادة (25) من القانون وتبليغها لطالب التنفيذ وأصحاب الحقوق الأخرى على المنقول الضامن المشهرة في السجل كما هي في اليوم السابق لتاريخ إيداع حصيلة البيع.
وللأشخاص المشار إليهم في الفقرة السابقة حق الاعتراض كتابة على القائمة المؤقتة خلال خمسة أيام من تاريخ تبليغهم، على أن يفصل القاضي المختص بالمحكمة الاقتصادية في الاعتراضات بصفة الاستعجال ويصدر قرارا بالقائمة النهائية للتوزيع.
وتتولى إدارة التنفيذ توزيع العوائد وحصيلة التنفيذ خلال سبعة أيام من تاريخ قرار القاضي المختص بالمحكمة الاقتصادية.
وترد للمدين أو مقدم الضمان بحسب الأحوال أي فوائض من حصيلة التنفيذ تزيد على الوفاء بحقوق الدائنين.$m246$,'0b55f8f712df6adb4f7a8443007e4adb'),
(42,0,$m246$المادة 42$m246$,$m246$إذا كانت حصيلة بيع المنقول الضامن والعوائد الناتجة عنه المنصوص عليها بالمادة (18) من القانون لا تكفي للوفاء بالتزامات وحقوق الدائنين المشهرة بالسجل فتوزع وفق الترتيب الآتي:
1- نفقات إصلاح المنقول الضامن وصيانته وإعداده للبيع.
2- رسوم ونفقات التنفيذ على المنقول الضامن.
3- سداد مستحقات أصحاب حقوق الضمان المشهرة على المنقول الضامن حسب أولويتها وفقا لأحكام هذا القانون.
4- سداد مستحقات أصحاب حقوق الامتياز وغيرها من الحقوق المقررة وفقا لأولويتها طبقا للقوانين المنظمة لها. ويكون لكل دائن مطالبة المدين بالباقي من قيمة الدين وعوائده وفقا للقواعد العامة المقررة في القانون لاستئداء الديون.$m246$,'7ccf3d1eef2cbeea0d57fb7b93f61618'),
(43,0,$m246$المادة 43$m246$,$m246$يجوز للمدين التصرف في المنقول أو تأجيره بعد سداد الدين المضمون أو بالباقي منه بحسب الأحوال وبعد خصم مقابل تعجيل الوفاء المتفق عليه في عقد الضمان، وذلك بعد حصوله على صورة من البيانات المشهرة بالسجل والتي تفيد شطب الشهر المقيد على حق الضمان المشهر أو إلغاءه سواء للوفاء بالدين المضمون في الميعاد المحدد له بمدة سريان الإشهار، أو حال القيام بالسداد المعجل أو بانقضاء حق الضمان لأي سبب.
ويجوز للمدين بيع المنقول أو تأجيره إلى شخص آخر محملا بحق الضمان ويكون المدين الأصلي ضامنا للمشتري أو المستأجر في تنفيذ التزاماته الناشئة عن عقد الضمان.$m246$,'b5ba95a0a54853c10a2c8769995ee42a');

INSERT INTO m246_ver VALUES
(0,0,1,$m246$قرار وزير الاستثمار رقم 108 لسنة 2016 بتاريخ 2016/12/15 بشأن إصدار اللائحة التنفيذية لقانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 .$m246$,'e8037055fae4810b735626b8461804c3',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$عنوان القرار كما طُبع بالمصدر. النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2)..$m246$),
(1,-1,1,$m246$يعمل بأحكام اللائحة التنفيذية لقانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 المرفقة.$m246$,'0502fb612eaab702b6e26b85230428aa',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(2,-1,1,$m246$ينشر هذا القرار واللائحة المرفقة في الوقائع المصرية، ويعمل بهما من اليوم التالي لتاريخ النشر.$m246$,'c6bea9c42be1f89e62b0dde152af015d',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(1,0,1,$m246$مع عدم الإخلال بالتعريفات الواردة في قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 المشار إليه، يكون لكل من الكلمات والعبارات الآتية المعنى المبين قرين كل منها عند تطبيق أحكام هذه اللائحة والقرارات التنظيمية الصادرة تنفيذا للقانون المشار إليه، ما لم ينص على خلاف ذلك صراحة:
القانون: قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015
الوزير المختص: الوزير المختص بتطبيق أحكام القانون رقم 10 لسنة 2009
الهيئة: الهيئة العامة للرقابة المالية باعتبارها الجهة الإدارية المختصة بتطبيق القانون وهذه اللائحة.
المنقول الضامن: كل منقول مادي قائم أو مستقبلي، أو منقول معنوي قائم مملوك للمدين أو مقدم الضمان أو الدائن، يكون ضمانا لالتزام أو دين أو تمويل أو تسهيل ائتماني، ويجب على الدائن مراعاة توافر الضوابط التالية في المنقول الضامن عند قيامه بإشهار حق الضمان بالسجل:
1- أن يكون من المنقولات المسموح قانونا بتداولها وبيعها في مصر.
2- أن يكون في حيازة المدين أو مقدم الضمان.
3- أن يكون مما يمكن التنفيذ عليه مستقلا عن غيره، أخذا في الاعتبار الأحكام الخاصة بالمنقولات المثلية والعقارات بالتخصيص الواردة بالقانون وهذه اللائحة.
المنقول المستقبلي: المنقول المادي المتوقع وجوده مستقبلا في ملكية المدين أو مقدم الضمان أو الدائن طبقا للمجرى العادي للأمور، ويقصد بالمجرى العادي للأمور الحالات التي تقتضي وفقا لطبيعة العمل أو المجال الذي يستخدم فيه المنقول محل الضمان أن يترتب عليها وجود المنقول وتملكه في المستقبل وتشمل على سبيل المثال لا الحصر عمليات الشراء والإنتاج والاستيراد وزراعة وبذر المحاصيل الزراعية.
المنقولات المثلية: هي المنقولات التي يقوم بعضها مقام بعض عند الوفاء، والتي تقدر عادة في التعامل بين الناس بالعدد أو المقاس أو الكيل أو الوزن، وبمراعاة الصفات والنوع وجهة الصنع أو الإنتاج.
مقومات المحل التجاري: مجموعة الأموال المنقولة والمخصصة لمزاولة تجارة معينة والتي يجوز شهر حق الضمان عليها كلها أو بعضها وتتضمن السمعة التجارية، والاسم التجاري، والسمة التجارية، والعلامات التجارية وبراءات الاختراع، والرسوم، والنماذج الصناعية، وحقوق الملكية الأدبية والفنية، وتراخيص الاستغلال والبضائع والأثاث والآلات والأجهزة والمعدات وغيرها من المهمات اللازمة لاستغلال المحل التجاري.
الدائن: المضمون له من البنوك أو الجهات التي تمارس نشاط التمويل وغيرها من الجهات والأشخاص المانحة للتمويل أو الائتمان وتشمل:
1- البنوك ومؤسسات التمويل المرخص لها بالعمل في مصر.
2- الشركات والجهات المرخص لها بممارسة نشاط التأجير التمويلي في مصر.
3- الجمعيات والمؤسسات الأهلية والشركات المرخص لها بممارسة نشاط التمويل متناهي الصغر في مصر.
4- الجهات المرخص لها بممارسة أنشطة متعلقة أو مرتبطة بتقديم تمويل أو ائتمان أو تقتضي طبيعة نشاطها المرخص لها به ذلك.
5- الأشخاص الاعتبارية والمنشآت الفردية المرخص لها بمزاولة أنشطة تجارة المنقولات التي يجوز قيد ضمان عليها وفقا للضوابط التي تحددها الهيئة.
6- الأشخاص الاعتبارية والأشخاص الطبيعيين مانحي رخص استخدام حقوق الملكية الفكرية.
المدين: الشخص الطبيعي أو الاعتباري الملتزم بالوفاء بالتزام أو دين مضمون.
مقدم الضمان: مالك المنقول الضامن، سواء المدين أو الغير.
الجهات المنصوص عليها بالمادة (13) من القانون: الجهات التي يخولها القانون صلاحية تحصيل حقوق الدولة أو غيرها من الحقوق المقررة قانونا بموجب الأحكام أو القرارات التي ترتب حقوقا على المنقولات.
طالب الإشهار: الشخص القائم بقيد الإشهار وتعديله وإلغائه والاعتراض عليه والبحث في السجل، سواء بالأصالة عن نفسه أو بالنيابة عن صاحب الحق المشهر.
الإشهار: قيد حق الضمان على الأموال المنقولة في السجل ويشمل ذلك الإشهار وتعديله والاعتراض عليه وإلغاءه.
السجل: سجل إشهار الضمانات المنقولة المنشأ وفقا لأحكام القانون.
المشغل: من يتولى إمساك وتشغيل سجل الضمانات المنقولة.
حق الضمان: الحق العيني التبعي الذي يقع على المنقول الضامن بموجب عقد الضمان المبرم بين الدائن والمدين أو مقدم الضمان لضمان الوفاء بالتزام أو دين.
عقد الضمان: العقد المبرم بين الدائن والمدين أو بين الدائن والمدين ومقدم الضمان والمثبت لحقوق الدائن على المنقول الضامن بالاسترشاد بالنموذج الذي تضعه الهيئة والذي يبين الشروط والأحكام الأساسية التي يجب أن يتضمنها العقد.$m246$,'504309783df780292d559d52449dce40',DATE '2016-12-16',DATE '2020-04-16','amended',908,2020,$m246$النص الأصلى قبل التعديل كما أورده المصدر تحت «نص المادة قبل التعديل»، ويسرى من 2016-12-16 (محسوب، انظر ملاحظة التاريخ) حتى استبداله بـقرار رئيس مجلس الوزراء رقم 908 لسنة 2020 (تاريخ العمل به 2020-04-16 بحسب مصدر ثانوى هو موقع منشورات، ولم يتضمنه الملف المرفوع).$m246$),
(1,0,2,$m246$مع عدم الإخلال بالتعريفات الواردة في قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 المشار إليه، يكون لكل من الكلمات والعبارات الآتية المعنى المبين قرين كل منها عند تطبيق أحكام هذه اللائحة والقرارات التنظيمية الصادرة تنفيذا للقانون المشار إليه، ما لم ينص على خلاف ذلك صراحة:
القانون: قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015
الوزير المختص: الوزير المختص بتطبيق أحكام القانون رقم 10 لسنة 2009
الهيئة: الهيئة العامة للرقابة المالية باعتبارها الجهة الإدارية المختصة بتطبيق القانون وهذه اللائحة.
المنقول الضامن: كل منقول مادي قائم أو مستقبلي، أو منقول معنوي قائم مملوك للمدين أو مقدم الضمان أو الدائن، يكون ضمانا لالتزام أو دين أو تمويل أو تسهيل ائتماني، ويجب على الدائن مراعاة توافر الضوابط التالية في المنقول الضامن عند قيامه بإشهار حق الضمان بالسجل:
1- أن يكون من المنقولات المسموح قانونا بتداولها وبيعها في مصر.
2- أن يكون في حيازة المدين أو مقدم الضمان.
3- أن يكون مما يمكن التنفيذ عليه مستقلا عن غيره، أخذا في الاعتبار الأحكام الخاصة بالمنقولات المثلية والعقارات بالتخصيص الواردة بالقانون وهذه اللائحة.
المنقول المستقبلي: المنقول المادي المتوقع وجوده مستقبلا في ملكية المدين أو مقدم الضمان أو الدائن طبقا للمجرى العادي للأمور، ويقصد بالمجرى العادي للأمور الحالات التي تقتضي وفقا لطبيعة العمل أو المجال الذي يستخدم فيه المنقول محل الضمان أن يترتب عليها وجود المنقول وتملكه في المستقبل وتشمل على سبيل المثال لا الحصر عمليات الشراء والإنتاج والاستيراد وزراعة وبذر المحاصيل الزراعية.
المنقولات المثلية: هي المنقولات التي يقوم بعضها مقام بعض عند الوفاء، والتي تقدر عادة في التعامل بين الناس بالعدد أو المقاس أو الكيل أو الوزن، وبمراعاة الصفات والنوع وجهة الصنع أو الإنتاج.
مقومات المحل التجاري: مجموعة الأموال المنقولة والمخصصة لمزاولة تجارة معينة والتي يجوز شهر حق الضمان عليها كلها أو بعضها وتتضمن السمعة التجارية، والاسم التجاري، والسمة التجارية، والعلامات التجارية وبراءات الاختراع، والرسوم، والنماذج الصناعية، وحقوق الملكية الأدبية والفنية، وتراخيص الاستغلال والبضائع والأثاث والآلات والأجهزة والمعدات وغيرها من المهمات اللازمة لاستغلال المحل التجاري.
الدائن: المضمون له من البنوك أو الجهات التي تمارس نشاط التمويل وغيرها من الجهات والأشخاص المانحة للتمويل أو الائتمان وتشمل:
1- الأشخاص الطبيعيين.
2- البنوك ومؤسسات التمويل المرخص لها بالعمل في مصر.
3- الشركات والجهات المرخص لها بممارسة نشاط التأجير التمويلي في مصر.
4- الجمعيات والمؤسسات الأهلية والشركات المرخص لها بممارسة نشاط التمويل متناهى الصغر في مصر.
5- الجهات المرخص لها بممارسة أنشطة متعلقة أو مرتبطة بتقديم تمويل أو ائتمان أو تقتضى طبيعة نشاطها المرخص لها به ذلك.
6- الأشخاص الاعتبارية والمنشآت الفردية المرخص لها بمزاولة أنشطة تجارة المنقولات التي يجوز قيد ضمان عليها وفقا للضوابط التي تحددها الهيئة.
7- الأشخاص الاعتبارية والأشخاص الطبيعيين مانحي رخص استخدام حقوق الملكية الفكرية.
المدين: الشخص الطبيعي أو الاعتباري الملتزم بالوفاء بالتزام أو دين مضمون.
مقدم الضمان: مالك المنقول الضامن، سواء المدين أو الغير.
الجهات المنصوص عليها بالمادة (13) من القانون: الجهات التي يخولها القانون صلاحية تحصيل حقوق الدولة أو غيرها من الحقوق المقررة قانونا بموجب الأحكام أو القرارات التي ترتب حقوقا على المنقولات.
طالب الإشهار: الشخص القائم بقيد الإشهار وتعديله وإلغائه والاعتراض عليه والبحث في السجل، سواء بالأصالة عن نفسه أو بالنيابة عن صاحب الحق المشهر.
الإشهار: قيد حق الضمان على الأموال المنقولة في السجل ويشمل ذلك الإشهار وتعديله والاعتراض عليه وإلغاءه.
السجل: سجل إشهار الضمانات المنقولة المنشأ وفقا لأحكام القانون.
المشغل: من يتولى إمساك وتشغيل سجل الضمانات المنقولة.
حق الضمان: الحق العيني التبعي الذي يقع على المنقول الضامن بموجب عقد الضمان المبرم بين الدائن والمدين أو مقدم الضمان لضمان الوفاء بالتزام أو دين.
عقد الضمان: العقد المبرم بين الدائن والمدين أو بين الدائن والمدين ومقدم الضمان والمثبت لحقوق الدائن على المنقول الضامن بالاسترشاد بالنموذج الذي تضعه الهيئة والذي يبين الشروط والأحكام الأساسية التي يجب أن يتضمنها العقد.$m246$,'301e1ee7a5ffbbb87448c02a5d14c252',DATE '2020-04-16',NULL,'active',908,2020,$m246$النص بعد استبداله بـقرار رئيس مجلس الوزراء رقم 908 لسنة 2020 (تاريخ العمل به 2020-04-16 بحسب مصدر ثانوى هو موقع منشورات، ولم يتضمنه الملف المرفوع) (علامة * بالمصدر). النص هنا هو الحالى كما طُبع بالمصدر.$m246$),
(2,0,1,$m246$تسري أحكام القانون وهذه اللائحة على الحقوق المضمونة بمنقول في حيازة المدين أو مقدم الضمان يتفق أطراف عقد الضمان على إشهاره وفقا لأحكام القانون وهذه اللائحة، على أن يكون محل إقامة أو المركز الرئيسي لأعمال المدين أو مقدم الضمان أو أحد فروع أي منهما التي تستفيد من التمويل يقع في جمهورية مصر العربية، بما في ذلك:
1- الحقوق المترتبة على بيع المنقول المشروط تأجيل نقل ملكيته لحين استيفاء الثمن.
2- الحقوق المترتبة على بيع المنقول المشروط استرداده أو إعادة شرائه عند إخلال المدين بالوفاء بالتزاماته.
3- الحقوق المترتبة على استخدام أو الترخيص باستخدام حقوق الملكية الفكرية.
وتسري أحكام القانون وهذه اللائحة المتعلقة بنفاذ حق الضمان في مواجهة الغير والأولوية والتنفيذ على المنقول الضامن على الحقوق الآتية:
1- حق الدائن في رهن الدين.
2- حق المؤجر بموجب عقود التأجير التمويلي أو التشغيلي الذي تزيد مدته على ستة أشهر.
3- حق مالك البضاعة برسم البيع.
4- حق الدائن في رهن المحل التجاري في حال قيامه بإشهاره وفقا لأحكام القانون.$m246$,'69005f3cfc5f1a74655a307446441838',DATE '2016-12-16',DATE '2020-04-16','amended',908,2020,$m246$النص الأصلى قبل التعديل كما أورده المصدر تحت «نص المادة قبل التعديل»، ويسرى من 2016-12-16 (محسوب، انظر ملاحظة التاريخ) حتى استبداله بـقرار رئيس مجلس الوزراء رقم 908 لسنة 2020 (تاريخ العمل به 2020-04-16 بحسب مصدر ثانوى هو موقع منشورات، ولم يتضمنه الملف المرفوع).$m246$),
(2,0,2,$m246$تسري أحكام القانون وهذه اللائحة على الحقوق المضمونة بمنقول في حيازة المدين أو مقدم الضمان يتفق أطراف عقد الضمان على إشهاره وفقا لأحكام هذا القانون وهذه اللائحة، على أن يكون المدين أو مقدم الضمان متمتعا بالأهلية، وأن يكون له حق إنشاء حق الضمان على المنقول الضامن، ويجب أن يكون محل إقامة أو المركز الرئيسي لأعمال المدين أو مقدم الضمان أو أحد فروع أي منهما التي تستفيد من التمويل يقع في جمهورية مصر العربية، بما في ذلك:
1- الحقوق المترتبة على بيع المنقول المشروط تأجيل نقل ملكيته لحين استيفاء الثمن.
2- الحقوق المترتبة على بيع المنقول المشروط استرداده أو إعادة شرائه عند إخلال المدين بالوفاء بالتزاماته.
3- الحقوق المترتبة على استخدام أو الترخيص باستخدام حقوق الملكية الفكرية.
وتسري أحكام القانون وهذه اللائحة المتعلقة بنفاذ حق الضمان في مواجهة الغير والأولوية والتنفيذ على المنقول الضامن على الحقوق الآتية:
1- حق الدائن في رهن الدين.
2- حق المؤجر بموجب عقود التأجير التمويلي أو التشغيلي الذي تزيد مدته على ستة أشهر.
3- حق مالك البضاعة برسم البيع.
4- حق الدائن في رهن المحل التجاري في حال قيامه بإشهاره وفقا لأحكام القانون.$m246$,'fbafb60c3f25de582896af22503ed4b4',DATE '2020-04-16',NULL,'active',908,2020,$m246$النص بعد استبداله بـقرار رئيس مجلس الوزراء رقم 908 لسنة 2020 (تاريخ العمل به 2020-04-16 بحسب مصدر ثانوى هو موقع منشورات، ولم يتضمنه الملف المرفوع) (علامة * بالمصدر). النص هنا هو الحالى كما طُبع بالمصدر.$m246$),
(3,0,1,$m246$يجوز إنشاء حق ضمان على المنقول المادي القائم أو المستقبلي، وكذلك على المنقول المعنوي القائم المملوك للمدين أو مقدم الضمان أو الدائن والموجود في حيازة المدين أو مقدم الضمان.
ولا يجوز إنشاء حق ضمان على المنقولات الآتية:
1- المنقولات المملوكة للدولة أو لهيئات وجهات الوقف، أو المملوكة للسفارات الأجنبية والهيئات التي تتمتع بالحصانة.
2- الامتيازات والتراخيص الممنوحة من الدولة، أو الهيئات العامة، أو أحد الأشخاص الاعتبارية العامة.
3- المنقولات التي تملكها البنوك عدا تلك اللازمة لعملها وبغرض تمويل شرائها.
4- المنقولات المخصصة لأغراض شخصية أو منزلية إلا لتمويل شرائها.
5- المنقولات المملوكة على الشيوع ما لم يوافق جميع المالكين على إنشاء حق الضمان، وفي هذه الحالة يجب أن يتضمن عقد الضمان توقيع جميع المالكين على الشيوع أو من ينوب عنهم قانونا بالموافقة على إنشاء حق الضمان.$m246$,'c0a911078053f1d404eeff7116bf56e7',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(4,0,1,$m246$لا تسري أحكام القانون وهذه اللائحة على الآتي:
1- الحقوق المترتبة على رهن الأوراق المالية المصرية أو الأجنبية أو شهادات الإيداع المقابلة لها سواء كانت مودعة بنظام الإيداع المركزي أم لم تكن مودعة.
2- الحقوق المترتبة على المنقول المستقبلي ويشمل كافة المبالغ والمنقولات التي من المتوقع أن يحصل عليها الشخص في الحالات التالية:
(أ) الميراث.
(ب) الوصية.
(جـ) المعاشات.
(د) وثائق التأمين على الحياة.
(هـ) التعويض بموجب اتفاق أو حكم.
(و) النفقة بموجب اتفاق أو حكم.
(ز) الأجور أو الرواتب ويقصد بها كل ما يتوقع أن يحصل عليه العامل مقابل عمله ثابتا كان أو متغيرا، نقدا أو عينا، بما في ذلك العمولة والنسبة المئوية والعلاوات أيا كان سبب استحقاقها أو نوعها والمزايا العينية والمنح والبدل ونصيب العامل في الأرباح والوهبة.$m246$,'45d9375a8c0747a6b84981b0c2f62a65',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(5,0,1,$m246$تنشئ الهيئة سجلا مركزيا إلكترونيا لإشهار حقوق الضمان على المنقولات، ويتم إشهار الحقوق في هذا السجل، كما يتم قيد أي تعديل أو شطب أي قيد أو إلغاؤه وفقا للضوابط الواردة في القانون وهذه اللائحة.
وفي جميع الأحوال يكون تقديم الخدمة من خلال الموقع الإلكتروني للسجل على مدار 24 ساعة يوميا ولسبعة أيام في الأسبوع عدا فترات الصيانة والدعم الفني أو الحالات الطارئة وحالات القوة القاهرة.
ويلتزم مشغل السجل بتوفير الخدمة للجمهور للإجابة عن الاستفسارات وفقا للمواعيد التي تحددها الهيئة.$m246$,'d343855d9afca8d756e02a5033d6f5a8',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(6,0,1,$m246$في حالة ما إذا عهدت الهيئة لإحدى الجهات أو الشركات المتخصصة بإنشاء وتشغيل السجل، يبقى إنشاء وتشغيل السجل خاضعا لإشراف ورقابة الهيئة وتكون الهيئة في جميع الأحوال هي المالكة لكافة البيانات والمعلومات المتاحة في السجل.
ويجب أن يتوافر في الجهة التي تعهد إليها الهيئة بإنشاء وتشغيل السجل على الأقل الشروط الآتية:
1- أن تكون ذات خبرة في مجالات إمساك السجلات أو الأنظمة الإلكترونية.
2- أن يكون لديها خبرة في مجال التطبيقات الرقمية من خلال استخدام التكنولوجيا.
3- أن يتوافر لدى القائمين على إدارتها الخبرات التكنولوجية والقانونية والإدارية اللازمة لإدارة وتشغيل السجل والتعامل مع طالبي الإشهار.
4- أن تتوافر لديها أنظمة تأمين البيانات والمعلومات وفقا للمعايير التي تحددها الهيئة.
5- أن تلتزم بالمواصفات الفنية لإنشاء وإدارة السجل وكذا أي تحديثات وتطويرات تطلبها الهيئة وخلال المدة التي تحددها.
6- أن تلتزم بإنشاء موقع إلكتروني على شبكة المعلومات الدولية، يمكن عن طريقه الاطلاع على البيانات المقيدة بالسجل، وذلك وفقا للمواصفات والضوابط التي تحددها الهيئة.
7- أن يكون لديها الملاءة المالية على الوفاء بالتزاماتها التعاقدية.
8- أن تبرم عقدا مع الهيئة ينظم حقوق والتزامات الجهة القائمة بإدارة السجل.
وتتولى الهيئة متابعة أعمال السجل والرقابة عليه ومتابعة شكاوى ومقترحات المتعاملين مع السجل وفحصها والبت فيها.$m246$,'e9bf430040531a8c5ddc390dc05cb464',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(7,0,1,$m246$الغرض من السجل هو قيد/ حفظ البيانات المشهرة من الدائنين أو الجهات المنصوص عليها بالمادة (13) من القانون أو المحكوم لصالحهم والمصفين والمتعلقة بالحقوق على المنقولات وإتاحتها للكافة وفقا لقواعد الاستخدام ومحددات البحث طبقا لأحكام هذه اللائحة والقواعد التي تضعها الهيئة، ويتولى السجل ومشغله على الأخص ما يلي:
1- السماح لطالبي الإشهار بقيد الإشهارات وتقديم طلبات البحث وإجرائها إلكترونيا بصورة مباشرة عبر الإنترنت أو نظم التواصل الشبكي المباشر.
2- توفير إمكانية الحصول على خدمات السجل وبيان أسباب رفض الإشهار.
3- الإعلان عن وسائل الحصول على خدمات السجل وأيام وأوقات عمل أي من مكاتب السجل.
4- تدوين المعلومات الواردة في طلب الإشهار المقدم إلى السجل في قيود السجل، وإدراج تاريخ كل تسجيل ووقته.
5- تخصيص رقم قيد غير مكرر للإشهار.
6- فهرسة المعلومات الواردة في قيود السجل أو تنظيمها على نحو آخر، لجعلها قابلة للبحث.
7- صون سلامة المعلومات الواردة في قيود السجل.
8- تزويد طالب الإشهار بنسخة من الإشهار المقيد.
9- إزالة المعلومات الواردة في الإشهار المسجل من قيود السجل عند انقضاء المدة المحددة بالإشهار.
10- حفظ المعلومات الخاصة بالإشهارات الملغاة من قيود السجل.
11- إعداد برامج لتوعية الجمهور، وتعميم مواد ترويجية وإيضاحية، وتنظيم دورات تدريبية وإعداد تعليمات مفصلة بشأن ملء نماذج الإشهارات وتقديمها والبحث في قيود السجل، ضمانا لسلاسة إنشاء وتشغيل السجل والإقبال عليه.
12- ضمان أن تكون مواصفات المعدات والبرمجيات بالسجل ذات سمات تقلل إلى أدنى حد ممكن من احتمال تلف البيانات أو ارتكاب أخطاء تقنية أو حدوث خروقات أمنية، مع الالتزام بحفظ نسخ احتياطية من كافة بيانات السجل في مكان آخر آمن وفقا للمعايير التي تضعها الهيئة.$m246$,'e2330759c68de39da14ff466b8def7a0',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(8,0,1,$m246$يقوم السجل بتقديم خدماته بمراعاة الضوابط الآتية:
1- تمكين مستخدمي السجل بشكل منتظم من فتح حساب لدى السجل لتيسير الانتفاع بالخدمات وتسديد أي مقابل ذي صلة.
2- المحافظة على أمن وسرية قاعدة بيانات السجل.
3- إمكانية قيام طالب الإشهار بإدخال تغييرات على البيانات التي يتم إشهارها.
4- إمكانية الحصول على تقارير عن المعاملات تتيح لطالبي الإشهار أن يتتبعوا معاملاتهم المقيدة في السجل على مدى فترة زمنية معينة.
5- إمكانية الحصول على نسخ من حقوق الضمان المشهرة والمقيدة في السجل ونتائج البحث.
6- إمكانية الحصول على تقارير إحصائية تتعلق بتشغيل السجل بما في ذلك البيانات الخاصة بحجم عمليات الإشهار والبحث ونفقات التشغيل أو مقابل الإشهار والبحث على مدى فترة زمنية معينة وغيرها من البيانات ذات الصلة بالقيد في السجل.
7- إمكانية إضافة خدمات أخرى لطالبي الإشهار والبحث وذلك بناء على طلب الهيئة أو بعد الحصول على موافقتها.$m246$,'adc599bd2dcac5917ac314ad74277c2d',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(9,0,1,$m246$يكون للبيانات المشهرة بالسجل المتعلقة بوقت الإشهار وتاريخه المصدق عليها من السجل حجية المحررات الرسمية في الإثبات، ولا تكون للبيانات والمعلومات المشهرة بالسجل المتاحة على أي موقع إلكتروني آخر بخلاف الموقع الإلكتروني الخاص بالسجل أية حجية في الإثبات.$m246$,'7b063821246fb09fe09d6d3eee825ede',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(10,0,1,$m246$يجوز لأي شخص البحث من خلال قواعد البيانات الخاصة في الموقع الإلكتروني للسجل. ولا يجوز إجراء البحث إلا عن طريق إدخال أحد المعايير الآتية:
1- رقم القيد غير المكرر للإشهار.
2- الرقم القومي للمدين/ مقدم الضمان إذا كان شخصا طبيعيا مصريا، أو رقم جواز سفره وبلد الإصدار حال كونه شخصا طبيعيا غير مصري، أو رقم تسجيله إذا كان شخصا معنويا، بحسب الأحوال.
وتقتصر المعلومات التي تظهر نتيجة البحث على ما يلي:
1- وجود إشهارات سارية مدرجة في السجل تحت رقم تسجيل غير مكرر أو تحت الرقم القومي للمدين/ مقدم الضمان أو رقم تسجيله، بحسب الأحوال.
2- رقم القيد غير المكرر لأي إشهار مدرج في السجل وتاريخه ووقته.
3- الرقم القومي/ رقم تسجيل المدين أو مقدم الضمان، بحسب الأحوال، واسم الدائن أو صاحب الحق المشهر بالسجل وعنوانه.
4- أي بيانات مدرجة في الإشهار فيما عدا تلك المعلومات المستخدمة لغايات إحصائية.
ولأي شخص قام بالبحث الحصول على نسخة من البيانات المدرجة في السجل تسمى ((تقرير البحث)) يصدر برقم تسجيل غير مكرر ويبين فيه البيانات الآتية:
1- وقت وتاريخ إجراء البحث.
2- المعيار المدخل من الشخص الذي أجرى البحث.
3- نتيجة البحث.
وتحفظ تقارير البحث في نظام السجل الإلكتروني ولكل ذي مصلحة بموجب إذن قضائي الحصول على نسخ ورقية معتمدة من نتائج البحث في السجل ويكون لها بعد تصديقها من السجل حجية في إثبات تاريخ الإشهار ووقته ومضمون ما طلب البحث عنه.$m246$,'de8a02d28b7fa8f37b1c48e84ba21363',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(11,0,1,$m246$يجوز لأي شخص الحصول على صور معتمدة من البيانات المدرجة في السجل بعد إدراج بياناته على نموذج الطلب المعد لذلك من الهيئة وتسديد المقابل المقرر لذلك.
وتحفظ طلبات الحصول على صور معتمدة في نظام السجل الإلكتروني ويكون للصور المعتمدة من الهيئة حجية في إثبات تاريخ طلب الحصول على صورة معتمدة ووقته ومضمون نتيجة البحث.$m246$,'9e5b156c397f5877a3cfb132164e1b24',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(12,0,1,$m246$تعتمد الهيئة دليلا يتضمن التعليمات الخاصة باستخدام السجل، والبيانات التي يتطلب السجل تقديمها لأغراض إحصائية.$m246$,'7cdf985882291ba86de75b048bb723e7',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(13,0,1,$m246$يتم شهر حق الضمان من خلال قيام الدائن باستيفاء النموذج الإلكتروني المعد لهذا الغرض على أن يتضمن كافة المعلومات الأساسية التي يتضمنها عقد الضمان وعلى الأخص وصف المنقول الضامن وصفا عاما أو خاصا وبيان أطراف عقد الضمان وصفاتهم بالنسبة لهذا المنقول الضامن ومدة الضمان، وذلك مع مراعاة حكم المادة (21) من هذه اللائحة.
وفيما عدا إشهار الإلغاء وتقديم الاعتراض، يجب موافقة المدين/ مقدم الضمان على قيد أي إشهار في السجل عن طريق توقيع عقد الضمان أو أية وثيقة أخرى تفيد موافقته.
ويعتبر الدائن مخالفا لأحكام القانون وهذه اللائحة حالة قيامه بقيد أي إشهار دون الحصول على موافقة المدين/ مقدم الضمان الخطية المسبقة.
واستثناء من حكم الفقرة السابقة يجوز للجهات المنصوص عليها بالمادة (13) من القانون والمحكوم لصالحهم والمصفين تسجيل الإشهارات دون الحصول على موافقة المدين/ مقدم الضمان.$m246$,'129469f80ba2d06a05720ca69615dd8f',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(14,0,1,$m246$مع مراعاة أحكام هذه اللائحة يتم قيد الإشهار في السجل بعد التأكد من استيفائه البيانات الآتية:
(أ) بيانات المدين/ مقدم الضمان، في حال كونه شخصا طبيعيا مصريا، فيتم إدخال رقمه القومي، وفي حال كونه شخصا طبيعيا غير مصري فيتم إدخال رقم جواز سفره وبلد الإصدار، وفي حالة الأشخاص المعنوية يتم إدخال رقم تسجيله أو إشهاره وفقا للقانون المنظم وفي جميع الأحوال يتم إدخال بيانات الاتصال الخاصة بالمدين/ مقدم الضمان.
(ب) بيانات طالب الإشهار، وفي حال كونه دائنا فيجب أن يتضمن اسمه ورقم تسجيله أو إشهاره وبيانات الاتصال الخاصة به، وفي حال الجهات المنصوص عليها بالمادة (13) من القانون فيتم إدخال اسم الجهة وشكلها القانوني وبيانات الاتصال الخاصة بها، وفي حال المحكوم لصالحه فإذا كان شخصا طبيعيا مصريا فيتم إدخال رقمه القومي، وفي حال كونه شخصا طبيعيا غير مصري فيتم إدخال رقم جواز سفره وبلد الإصدار، وفي حالة الأشخاص المعنوية يتم إدخال رقم تسجيله أو إشهاره وفقا للقانون المنظم وفي جميع الأحوال يتم إدخال بيانات الاتصال الخاصة به، وفي حال المصفي فيتم إدخال رقمه القومي وبيانات الاتصال الخاصة به.
(جـ) وصفا للمنقول موضوع الإشهار، ويجوز أن يكون الوصف عاما أو خاصا ما دام دالا على الموصوف، وفي حال كون المنقول الضامن أشياء مخصصة لأغراض الاستعمال الشخصية أو المنزلية فيجب أن يكون وصفها محددا.
وفي حال كون المنقول الضامن عقارا بالتخصيص فيجب إدخال البيانات المتعلقة بالعقار الذي خصص له حسبما هي واردة في سجلات الشهر العقاري.
(د) مدة سريان الإشهار.
(هـ) قيمة الالتزام المقرر على المنقول الضامن عند قيد الإشهار في السجل.
(و) البيانات الأخرى التي يطلبها السجل لاستخدامها لغايات إحصائية.$m246$,'7384822b985a32a991d7ed3c0ef9a9ea',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(15,0,1,$m246$لا يقبل قيد أي إشهار في السجل بما في ذلك إشهارات الجهات المنصوص عليها بالمادة (13) والمحكوم لصالحهم والمصفين ما لم يكن مستوفيا للشروط والبيانات والإجراءات المحددة في القانون وهذه اللائحة وفقا للنموذج المعد من الهيئة.
وفي حالة استيفاء البيانات المطلوبة في السجل، تقبل عملية الإشهار ويتم إصدار تأكيد إلكتروني للتسجيل يتضمن تاريخ الإشهار ووقته ورقم القيد وكافة المعلومات المدرجة في عملية الإشهار، ولطالب الإشهار طباعة هذا التأكيد لاستخدامه في إثبات قيامه بتسجيل الإشهار.
ويصدر النظام الإلكتروني عند قيد كل إشهار رقما متسلسلا خاصا يستخدم لاحقا للتحقق من رقم الإشهار عند إدخاله في الإشهارات اللاحقة المتعلقة بذلك الإشهار.
ويحدد السجل مدى كفاية المعلومات المقدمة للإشهار وفقا لبرنامج تشغيله الإلكتروني وفي حال عدم كفايتها يظهر رسالة إلكترونية تحدد أسباب الرفض وما يلزم لاستكمالها.
ويعتبر الإشهار نافذا بمجرد قبول عملية الإشهار وظهور المعلومات الآتية في السجل:
1- تاريخ الإشهار ووقته.
2- رقم إشهار غير مكرر صادر عن السجل لكل إشهار.
3- البيانات المدرجة في الإشهار فيما عدا تلك البيانات المستخدمة لغايات إحصائية.
ومع عدم الإخلال بالحجية المقررة لتاريخ الشهر، لا يعتبر قبول تسجيل الإشهار دليلا على كفايته من الناحية القانونية، ولا دليلا على دقة المعلومات التي يتضمنها.
وللمحكمة أن تقرر عدم اعتبار الإشهار نافذا في حال وجود خطأ في بيانات المدين أو في بيانات المنقول الضامن يمنع من إظهار الإشهار عند إجراء عملية البحث.
وينحصر أثر حصول الخطأ في إدخال بيانات المنقول الضامن على نفاذ الإشهار بخصوص هذا المنقول، كما ينحصر أثر حصول الخطأ في بيانات المدين على نفاذ الإشهار بخصوص ذلك المدين.$m246$,'289fc693f6ec383ea2e993c36665c629',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(16,0,1,$m246$يلتزم الدائن قبل القيام بعملية الإشهار بفتح حساب لدى مشغل السجل.
ويكون طالب الإشهار مسئولا عن صحة البيانات التي يضمنها في نموذج الإشهار، وفي حال قيامه بإدخال المعلومات مباشرة على الموقع الإلكتروني لا يكون السجل مسئولا عن صحة البيانات والمعلومات الواردة في الإشهار أو المستندات المرفقة به، ويكون الدائن مسئولا عن تعويض الأضرار التي قد تترتب للهيئة أو ذوي الشأن أو الغير الناشئة عن البيانات والمعلومات الخاطئة الواردة في الإشهار.
وفي الحالات المنصوص عليها بالمادة (21) من هذه اللائحة، يقوم السجل باستيفاء نموذج الإشهار بناء على نموذج ورقي مقدم من طالب الإشهار وموقع منه ويكون طالب الإشهار مسئولا عن دقة البيانات التي ضمنها في النموذج الورقي ويقوم السجل بتسجيل النموذج إلكترونيا فور وروده ويبقى السجل مسئولا عن تصحيح أي خطأ في إدخال البيانات في السجل الإلكتروني، ويقوم بتصحيح البيانات فور اكتشاف الخطأ عن طريق تسجيل إشهار معدل مع إرسال نسخة من الإشهار المعدل للدائن أو صاحب الحق المشهر بالسجل.$m246$,'7e97525f0aaa34e2368bcb845081fe92',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(17,0,1,$m246$يكون الإشهار وأي تعديل عليه نافذا بمجرد ظهوره ضمن قواعد بيانات السجل وللمدة المحددة فيه.
وفي جميع الأحوال يتم إخطار المدين/ مقدم الضمان بالإشهارات المقيدة وفقا للوسائل والمواعيد التي تحددها الهيئة.$m246$,'be069b6a629e87bab27133a06a540c5f',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(18,0,1,$m246$يجوز تعديل الإشهار المقيد عن طريق إشهار تعديل على أن يتضمن، بالإضافة للمعلومات المطلوبة لتسجيل الإشهار، ما يلي:
1- رقم القيد غير المكرر للإشهار.
2- اسم طالب الإشهار الذي يجري التعديل أو صاحب الحق المشهر بالسجل وصفته.
ويجوز مد مدة الإشهار المسجل قبل انتهاء مدته وذلك عن طريق تسجيل إشهار تعديل يتضمن في الخانة المخصصة مدة أخرى للسريان، وعند قبول إشهار التعديل بمد مدة السريان يعتبر الإشهار ممددا للمدة المحددة في إشهار التعديل والتي تبدأ من تاريخ انتهاء المدة التي تم مدها.
وعدا الحالات التي يكون فيها التعديل لمصلحة المدين/ مقدم الضمان فإذا كان موضوع الإشهار المعدل إضافة منقول ضامن أو مدين أو مقدم ضمان أو تمديد سريان الإشهار أو زيادة قيمة الالتزام المضمون، فيجب الموافقة عليه من المدين/ مقدم الضمان.
وفي جميع الأحوال تكون مرتبة حقوق الدائن عند التعديل بزيادة الالتزامات أو مدة الضمان أو إضافة منقولات أخرى أو استبدالها من تاريخ إشهار التعديل فيما يتعلق بهذه التعديلات.$m246$,'d1c552c65b7ed96e9e77657a11eae54a',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(19,0,1,$m246$يكون لأي شخص تم إدراج اسمه كمدين/ مقدم الضمان أو محكوم عليه في أي إشهار أن يتقدم باعتراض إلى السجل على الإشهار أو أي من البيانات الواردة به على أن يتضمن الاعتراض ما يلي:
1- اسم المعترض.
2- رقم القيد للإشهار المعترض عليه.
3- بيان أسس الاعتراض، بما في ذلك الادعاء بعدم صحة الإشهار أو عدم دقة المعلومات الواردة فيه.
4- أي بيانات أخرى يطلبها المشغل.
ويقوم السجل بإخطار الدائن بالاعتراض إلكترونيا والرد على مقدم الاعتراض خلال أسبوع من تاريخ تقديمه بما انتهت إليه الإجراءات.
وفي جميع الأحوال، يجوز لكل ذي مصلحة الاعتراض لدى قاضي الأمور المستعجلة على ما يرد من إشهار لحقوق الضمان بالسجل، دون أن يؤثر هذا الاعتراض على نفاذ حق الضمان في مواجهته أو مواجهة الغير.$m246$,'3c283e089005a4eb4f05d829f6f92fd6',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(20,0,1,$m246$في الأحوال التي ينقضي فيها حق الضمان قبل انتهاء مدة الإشهار بالسجل، سواء بسبب عدم موافقة المدين أو مقدم الضمان على تسجيل الإشهار أو الإبراء أو الأداء أو لأي سبب آخر يلتزم الدائن أو غيره من أصحاب الحقوق المشهرة بالسجل بإلغاء الإشهار خلال عشرة أيام على الأكثر من تاريخ تحقق الواقعة المنشئة لانقضاء حق الضمان.
ويستوفي الدائن أو غيره من أصحاب الحقوق المشهرة بالسجل النموذج الإلكتروني للإلغاء والمعد لهذا الغرض بالسجل والذي يجب أن يتضمن:
1- رقم القيد غير المكرر للإشهار.
2- اسم طالب الإشهار الذي يجري الإلغاء أو صاحب الحق المشهر بالسجل وصفته.
3- إقرار بأن الإشهار المطلوب إلغاؤه أصبح غير نافذ في مواجهة الدائن أو صاحب الحق المشهر بالسجل طالب الإلغاء، وكذا غير نافذ في مواجهة المدين/ مقدم الضمان والغير.
ويستمر عرض الإشهار الملغي (مع بيان أنه قد ألغى) ضمن قواعد بيانات السجل إلى حين انقضاء مدته.
ولا يسري الإلغاء في مواجهة أي دائن تم إشهار حقوقه على ذات المنقول الضامن في ذات العقد ما لم يوافق على الإلغاء.
وفي حالة عدم قيام الدائن أو غيره من أصحاب الحقوق المشهرة بالسجل بإلغاء الإشهار خلال المدة المحددة أعلاه، فللمدين أو مقدم الضمان أو كل ذي صفة أو مصلحة أن يقدم عريضة بذلك لقاضي الأمور المستعجلة لإصدار أمر بإلغاء القيد موضحا به سبب انقضاء حق الضمان، ويصدر قاضي الأمور المستعجلة أمرا بإلغاء الإشهار خلال يومي عمل على الأكثر من تاريخ تقديم الطلب ويتولى السجل إلغاء الإشهار في قيوده لدى استلام نسخة رسمية من الأمر الصادر عن قاضي الأمور المستعجلة بالإلغاء.$m246$,'ac12b2a49dc2b2346afb4ad9a04223e8',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(21,0,1,$m246$يجب على المحكمة المختصة بناء على طلب كتابي من المحكوم لصالحه، التصريح له بشهر الحقوق المترتبة على منقولات المدين في الحالتين التاليتين:
1- صدور حكم وقتي نهائي بتوقيع حجز تحفظي على هذه المنقولات.
2- صدور حكم وقتي نهائي بالتنفيذ على هذه المنقولات.
وفي حال اتفاق الشركاء/ المساهمين بتصفية الشركة اختياريا يقوم المصفي المعين من قبل الشركاء/ المساهمين بإشهار قرار التصفية الاختيارية، كما يلتزم المصفي بإشهار التصفية الإجبارية بالسجل.
وفي الحالات المشار إليها بالفقرتين السابقتين يقوم المحكوم لصالحه أو المصفي بحسب الأحوال بتعبئة نموذج الإشهار بناء على نموذج ورقي مقدم من طالب الإشهار وموقع منه ومرفقا به صورة موثقة من القرار أو الحكم، ويكون طالب الإشهار مسئولا عن دقة البيانات التي ضمنها في النموذج الورقي ويقوم مشغل السجل بتسجيل النموذج إلكترونيا فور وروده، شريطة تحميل صورة إلكترونية من الحكم أو القرار المطلوب إشهاره على قاعدة بيانات السجل وذلك بمراعاة الفقرة الثانية من المادة (16) من هذه اللائحة.
وتقوم المحكمة التي أصدرت حكما بإشهار الإفلاس بإصدار أمر للسجل لإشهار ذلك الحكم ويقوم السجل بتسجيل النموذج إلكترونيا فور وروده وتحميل صورة إلكترونية من الحكم المطلوب إشهاره على قاعدة بيانات السجل وذلك بمراعاة الفقرة الثانية من المادة (16) من هذه اللائحة.
وعلى الجهات المنصوص عليها بالمادة (13) من القانون إشهار الأحكام أو القرارات التي ترتب حقوقا على المنقولات مباشرة من خلال الموقع الإلكتروني للسجل عن طريق استيفاء النموذج المعتمد من الهيئة شريطة تحميل صورة إلكترونية من الحكم أو القرار المطلوب إشهاره على قاعدة بيانات السجل.
وتعفي عمليات الإشهار المنصوص عليها في هذه المادة من الرسوم المنصوص عليها في هذه اللائحة.$m246$,'488903cd45995e8f65d5a44dd052af63',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(22,0,1,$m246$يلزم لإشهار الحقوق الواردة بهذا الفصل مراعاة أحكام المواد (1) 6)، (15)، (14)، (13 بالإضافة للإجراءات الواردة بهذا الفصل.$m246$,'2daab5be7a89040f26975463fbe5488d',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(23,0,1,$m246$مع عدم الإخلال بحقوق البنك على الحسابات والشهادات والودائع لديه، يكون للدائن إشهار حقوق ضمان على الحسابات المصرفية أو الشهادات البنكية أو الودائع الخاصة بالمدين في أحد البنوك باستيفاء النموذج الإلكتروني الخاص بذلك على أن يرفق به إلكترونيا خطاب حديث معتمد من البنك المفتوح لديه الحساب أو الصادر منه الشهادة البنكية أو المودع لديه الوديعة موجه للسجل يفيد عدم اعتراضه على إشهار حق الضمان بالقيمة الواردة به على الحساب أو الشهادة أو الوديعة لديه.
ويلتزم الدائن خلال أسبوع من تاريخ الإشهار بإخطار البنك المفتوح لديه الحساب أو الصادر منه الشهادة البنكية أو المودع لديه الوديعة بالإشهارات التي تمت بالسجل على الحسابات المصرفية أو الشهادات البنكية أو الودائع لديه.$m246$,'c0ec4ad0f781a244a6e3cd0ca1420d8a',DATE '2016-12-16',DATE '2020-04-16','amended',908,2020,$m246$النص الأصلى قبل الإلغاء كما أورده المصدر تحت «نص المادة قبل الإلغاء»، ويسرى من 2016-12-16 (محسوب) حتى إلغائه بـقرار رئيس مجلس الوزراء رقم 908 لسنة 2020 (تاريخ العمل به 2020-04-16 بحسب مصدر ثانوى هو موقع منشورات، ولم يتضمنه الملف المرفوع).$m246$),
(23,0,2,$m246$ملغاة$m246$,'e92ebe02473ae540e86780a17ab84d1b',DATE '2020-04-16',NULL,'repealed',908,2020,$m246$ملغاة بـقرار رئيس مجلس الوزراء رقم 908 لسنة 2020 (تاريخ العمل به 2020-04-16 بحسب مصدر ثانوى هو موقع منشورات، ولم يتضمنه الملف المرفوع) (علامة * بالمصدر). لا نص تشغيلى حالياً تحت هذا الترقيم؛ النص الملغى محفوظ فى النسخة السابقة.$m246$),
(24,0,1,$m246$يجوز للدائن المرتهن حيازيا إشهار رهنه في السجل عن طريق استيفاء النموذج الإلكتروني المعد من الهيئة لهذا الغرض، على ألا يخل ذلك بنفاذ حقه على المال المرهون في مواجهة الغير وفقا لأحكام القانون المدني.
ويترتب على إشهار الرهن الحيازي وفقا لأحكام القانون وهذه اللائحة قيام الدائن المرتهن حيازيا بنقل حيازة المنقول الضامن إلى المدين أو مقدم الضمان بحسب الأحوال.
ويمنح إشهار الرهن الحيازي الدائن المرتهن الحقوق التي يتمتع بها كما لو كان حائزا للمال المرهون بما في ذلك حق تتبعه في يد حائزه وتقدم الدائنين الآخرين في استيفاء الدين من حصيلة بيع المرهون عند التنفيذ عليه وفقا لأحكام القانون.$m246$,'a25af077a4c5f69d0db4ad65493d02ee',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(25,0,1,$m246$يتم شهر حقوق الضمان على مقومات المحل التجاري بالسجل من خلال قيام الدائن باستيفاء النموذج الإلكتروني الخاص بذلك على أن يرفق به إلكترونيا مستخرج رسمي حديث لا يزيد تاريخ إصداره على شهر من السجل التجاري ببيانات الرهون المثبتة عليه وغيره من الحقوق المشهرة وآجالها وقيمة الالتزام المشهر بالسجل وبيانات الدائن.
ويقوم السجل بإخطار السجل التجاري بكافة الإشهارات التي تمت بالسجل على مقومات المحل التجاري أو أي تعديل أو إلغاء لها على أن يكون الإخطار إلكترونيا كلما كان ذلك ممكنا.
ويلتزم الدائن بإخطار السجل والسجل التجاري فور البدء في إجراءات التنفيذ على مقومات المحل التجاري.
وفي حال قيام الدائن بإلغاء الإشهار بالسجل يلتزم الدائن باستيفاء النموذج الإلكتروني الخاص بذلك على أن يرفق به إلكترونيا شهادة حديثة من السجل التجاري بشطب الرهن من السجل التجاري.$m246$,'b6a179508bba41a8f191daaf298536a9',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(26,0,1,$m246$يتم شهر حقوق الضمان على حقوق الملكية الفكرية بالسجل من خلال قيام الدائن باستيفاء النموذج الإلكتروني الخاص بذلك.
على أن يرفق به إلكترونيا مستخرج رسمي حديث لا يزيد تاريخ إصداره على شهر من الجهة القائمة على رهن حقوق الملكية الفكرية وفقا للقانون رقم 82 لسنة 2002 والموجه للسجل بتاريخ قيد هذه الحقوق ومدى وجود رهون عليها وآجالها وقيمة الالتزام المشهر وبيانات الدائن.
ويقوم السجل بإخطار الجهة القائمة على رهن حقوق الملكية الفكرية إلكترونيا بشكل أسبوعي بكافة الإشهارات التي تمت بالسجل على حقوق الملكية الفكرية أو أي تعديل أو إلغاء لها.
ويلتزم الدائن بإخطار السجل والجهة القائمة على رهن حقوق الملكية الفكرية فور البدء في إجراءات التنفيذ على حقوق الملكية الفكرية.
وفي حال قيام الدائن بإلغاء القيد بالسجل يلتزم الدائن باستيفاء النموذج الإلكتروني الخاص بذلك على أن يرفق به إلكترونيا شهادة حديثة من الجهة القائمة على رهن حقوق الملكية الفكرية بشطب الرهن لديها.$m246$,'17b375c2423eb6d966ff65d197adb608',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(27,0,1,$m246$يجوز للدائن أو لأصحاب الحقوق المقررة بموجب المادة (13) من القانون شهر الحقوق المنشأة لصالحهم على المنقولات قبل العمل بأحكام هذا القانون والسارية في تاريخ العمل به وفقا للقوانين المنظمة لها.
والتي كانت ستخضع له فيما لو كان القانون ساريا عند إبرامها، وذلك وفقا لأحكام القانون وهذه اللائحة.
ويتولى المشغل الإعلان عن مواعيد قيام الدائنين بإشهار حقوقهم طبقا للمادة الرابعة من مواد إصدار القانون. وعلى الدائنين الالتزام بهذه المواعيد.$m246$,'d7cfc9eaefd431afa1426810c6ae0760',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(28,0,1,$m246$يستحق مقابل عن إشهار الحقوق بالسجل أو تعديله أو الاطلاع على البيانات المشهرة وفقا للجدولين الملحقين بهذه اللائحة.
وتكون مصروفات الإشهار وتجديده وتعديله على الدائن ما لم يتفق على خلاف ذلك، ويعفي إلغاء الإشهار وشطبه من أي رسوم أو مصروفات.
وتحدد الهيئة وسائل سداد هذا المقابل.$m246$,'508afe091812bf3b4281206cfd10d1d2',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(30,0,1,$m246$يجوز للدائن التنازل عن حق الضمان المشهر إلى شخص آخر ويسري هذا التنازل في حق الغير من تاريخ إشهاره بالسجل، ولا يسري التنازل في حق المدين أو مقدم الضمان إلا من تاريخ إخطارهما به بالطريقة المحددة في عقد الضمان.
ويقوم الدائن بإشهار التنازل عن حق الضمان باستيفاء النموذج الإلكتروني المعد لهذا الغرض بالسجل، على أن يتضمن التنازل عن الحق البيانات الخاصة بالمتنازل إليه.
ويكون للمتنازل إليه ذات حقوق ومرتبة الدائن المتنازل.$m246$,'23d8de5e106e20c86c030fb706729bc0',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(31,0,1,$m246$يجوز للدائن التنازل كتابة عن مرتبة الأولوية لحق الضمان المقرر له وفقا لأحكام هذا القانون في حدود الدين المتنازل عنه المضمون بهذا الحق، ويكون هذا التنازل نافذا في مواجهة الغير من تاريخ إشهار هذا التنازل بالسجل.
ويقوم الدائن بإشهار التنازل عن مرتبة الأولوية لحق الضمان المقرر له باستيفاء النموذج الإلكتروني المعد لهذا الغرض بالسجل، ويجب أن يتضمن التنازل البيانات الخاصة بالمتنازل إليه، ويكون للمتنازل إليه ذات حقوق ومرتبة الدائن المتنازل في حدود دين المتنازل.$m246$,'a7107ceeebf371860b85e2bb3bed42d4',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(32,0,1,$m246$يجوز إنشاء حق ضمان على العقار بالتخصيص شريطة إمكانية فصله عن العقار دون أن ينشأ عن ذلك ضرر لأي منها.
تحدد مرتبة الضمان في هذه الحالة من تاريخ إشهاره في السجل وفقا للإجراءات المحددة في القانون وهذه اللائحة لإشهار حق الضمان وتسجيله في صحيفة العقار قبل توثيق أي حقوق أخرى على العقار، ويتقدم هذا الحق على الحقوق العينية الأخرى الواقعة على العقار بشرط التأشير بتسجيل حق الضمان في صحيفة الشهر العقاري إذا كان العقار مسجلا.
وإذا أصبح المنقول الضامن عقارا بالتخصيص يستمر نفاذ حق الضمان في مواجهة الغير ويتقدم الحقوق العينية الأخرى الواقعة على العقار بشرط التأشير بتسجيل حق الضمان في صحيفة الشهر العقاري إذا كان العقار مسجلا.
وإذا كان العقار غير مسجل، تحدد مرتبة الأولوية لحق الضمان على العقار بالتخصيص من تاريخ إشهاره في السجل.$m246$,'21cbb2e9e7c1653ab3e9f4487480c651',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(33,0,1,$m246$إذا حصل المدين على تمويل لشراء منقولات تشكل في الأحوال العادية جزءا من منقولات سبق إنشاء حقوق ضمان عليها، يكون لممول شراء المنقولات الإضافية أولوية في استيفاء حقوقه منها وفقا للشروط الآتية:
1- قيام الدائن باستيفاء إجراءات الإشهار بالسجل خلال مدة لا تجاوز ثلاثة أيام عمل من تاريخ حيازتها.
2- قيام الدائن بإخطار الدائنين الآخرين المقيدة حقوقهم على المنقول وفقا لبيانات الاتصال الخاصة بهم في البيانات المقيدة في السجل.$m246$,'2a3de09933415b2942c206c119834722',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(34,0,1,$m246$في حالة إنشاء حق ضمان على منقولات مثلية فيستمر نفاذ حق الضمان إذا اختلطت تلك المنقولات بمثيلاتها، وفي هذه الحالة تتساوى حقوق الضمان النافذة تجاه الغير على مجموع المنقولات المثلية في المرتبة، ويتحدد حق كل دائن بنسبة دينه المضمون لإجمالي المنقولات المختلطة اعتبارا من تاريخ الاختلاط.$m246$,'ae02e2fbaca03496769884574067af5a',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(35,0,1,$m246$في حال إنشاء حق ضمان على منقولات تدخل ضمن مكونات إنتاج سلعة أو منتج، فيجب لسريان الإشهار أن تتضمن بيانات الإشهار ما ستؤول إليه هذه المنقولات من سلع أو منتج نهائي متضمنة عددها و/أو كميتها ونسبة حق الضمان لإجمالي قيمة هذه السلع أو المنتجات.
وفي حال وجود حقوق ضمان مشهرة على أكثر من منقول ضمن مكونات إنتاج السلعة أو المنتج النهائي وتضمين بيانات الإشهار ما ستؤول إليه هذه المنقولات من سلع أو منتج نهائي، فتسري حقوق الضمان المشهرة للدائنين على عدد و/أو كمية السلعة أو المنتج النهائي وتتساوى جميع حقوق الضمان المشهرة في الأولوية كل بنسبة حق ضمانه لإجمالي قيمة السلعة أو المنتج.$m246$,'71e68d6841389a80a36f188ee4c113b9',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(36,0,1,$m246$إذا منح عقد الضمان الدائن الحق ببيع المنقول الضامن إذا لم يقم المدين بتنفيذ التزاماته أو بتسديد الدين المضمون أو الأقساط في المواعيد ووفقا للشروط المتفق عليها في العقد، يكون المنقول الضامن قابلا للتنفيذ عليه إذا تخلف المدين عن تنفيذ التزاماته بموجب عقد الضمان، وفي هذه الحالة يكون للدائن القيام بما يلي:
1- حيازة المال المنقول الضامن بشكل مباشر أو غير مباشر.
2- التصرف في المنقول الضامن.
3- ممارسة أي من الحقوق الواردة في عقد الضمان أو في القانون أو أي قانون آخر.
ولا يجوز للدائن البدء في إجراءات البيع إلا بعد مضي خمسة أيام من تكليف المدين بالوفاء بموجب كتاب مسجل مصحوب بعلم الوصول، وكذلك إخطار الدائنين المشهرة حقوقهم المضمونة على المنقول الضامن بذلك بموجب كتاب مصحوب بعلم الوصول على عناوينهم المشهرة قبل البدء في إجراءات البيع بخمسة أيام على الأقل.
وعلى الدائن الالتزام بالإجراءات التي تضمنها عقد الضمان المنظمة لعملية البيع وتوزيع حصيلته ويجب على المدين تمكينه من حيازة المنقول الضامن، فإذا امتنع عن ذلك كان للدائن أن يطلب بناء على عريضة تقدم إلى القاضي المختص بالمحكمة الاقتصادية التي يقع في دائرتها موطن المدين؛ الأمر بتسليمه المنقول الضامن، ويصدر القاضي أمر التسليم خلال ثلاثة أيام عمل على الأكثر من تاريخ تقديم الطلب إليه ويتم تنفيذ الأمر بالطرق الجبرية المقررة قانونا.$m246$,'ca128292a246e4595894e7c398fca92f',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(37,0,1,$m246$إذا لم يتضمن عقد الضمان حق الدائن في اتخاذ إجراءات البيع مباشرة في حالة إخلال المدين بالتزاماته، كان للدائن بعد انقضاء خمسة أيام من تاريخ تكليف المدين بالوفاء أن يطلب بناء على عريضة تقدم إلى القاضي المختص بالمحكمة الاقتصادية التي يقع في دائرتها موطن المدين؛ الأمر ببيع المنقول الضامن كله أو بعضه.
ولا يجوز تنفيذ الأمر الصادر عن القاضي ببيع المنقول الضامن إلا بعد انقضاء خمسة أيام من تاريخ إخطاره إلى المدين بموجب كتاب مصحوب بعلم الوصول وإخطار الدائنين المشهرة حقوقهم المضمونة بموجب كتاب مصحوب بعلم الوصول قبل التنفيذ بخمسة أيام على الأقل مع بيان المكان الذي يجري فيه البيع وتاريخه وساعته، ويجري البيع في الزمان والمكان اللذين عينهما القاضي وبالطريقة التي يحددها بما يتناسب مع طبيعة المنقول الضامن.$m246$,'b7d2d3c8b6cc948d9a6a1d81b548c7a1',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(38,0,1,$m246$للدائن بيع المنقول الضامن دون اتباع الإجراءات والمدد الواردة بالمادتين السابقتين في أي من الحالات الآتية:
1- عدم وجود حقوق مضمونة لدائنين آخرين على ذات المنقول الضامن وموافقة المدين على البيع.
2- الحالات التي تقل فيها المدة المقررة لصلاحية المنقول الضامن عن مجموع المدد اللازمة لتكليف المدين بالوفاء وإخطار الدائنين الآخرين المشهرة حقوقهم على هذا المنقول وإنهاء بيع المنقول الضامن وتسليمه للمشتري وفقا للإجراءات المحددة بالقانون وهذه اللائحة، وبشرط قيام الدائن بإخطار مقدم الضمان والدائنين الآخرين المشهرة حقوقهم بالسجل -حال وجودهم -بوقت البيع ومكانه ومقدار الدين الذي يجري البيع لسداده وذلك بموجب خطاب مسجل مصحوب بعلم الوصول قبل البدء في البيع بيوم عمل على الأقل.
3- الحالات التي تقل فيها القيمة التقديرية للمنقول الضامن عن عشرة آلاف جنيه، وبشرط قيام الدائن بإخطار مقدم الضمان والدائنين الآخرين المشهرة حقوقهم بالسجل -حال وجودهم -بوقت البيع ومكانه ومقدار الدين الذي يجري البيع لسداده وذلك بموجب خطاب مسجل مصحوب بعلم الوصول قبل البدء في البيع بثلاثة أيام عمل على الأقل.
ويجب على الدائن أن يبذل في ذلك العناية التي يبذلها في أعماله الخاصة، ويكون الدائن مسئولا عن تعويض مقدم الضمان والمدين وأي من أصحاب الحقوق الأخرى على المال الضامن عن الأضرار الناتجة عن مخالفته لإجراءات التنفيذ المبينة في هذه اللائحة.
وفي جميع الأحوال، يترتب على بيع المنقول الضامن تطهير المنقول الضامن من كافة الديون وتنتقل حقوق الدائنين إلى الثمن.$m246$,'e39f71d377cda507efa7bc9e89d76cb2',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(39,0,1,$m246$يجب أن يلصق على باب المكان الموجودة به المنقولات محل البيع وفي اللوحة المعدة لذلك بالمحكمة المختصة إعلانات يبين فيها يوم البيع وساعته ونوع الأشياء محل البيع ووصفها بالإجمال.
وإذا تضمن عقد الضمان أن يتم النشر في الصحف عند اتخاذ إجراءات البيع فيجب الإعلان عن البيع بالنشر في إحدى الصحف اليومية، ويذكر في الإعلان يوم البيع وساعته ومكانه ونوع المنقولات محل البيع ووصفها بالإجمال، وإذا لم يتضمن عقد الضمان اتفاقا على النشر في الصحف، يجوز للدائن أو المدين أو مقدم الضمان أن يطلب من المحكمة المختصة النشر على نفقته الخاصة.
وإذا تضمن عقد الضمان حق الدائن بيع المنقول الضامن فيجري البيع في المكان الذي توجد فيه المنقولات، وإذا لم يتضمن عقد الضمان ذلك فيجري البيع في الزمان والمكان اللذين عينهما القاضي بما يتناسب مع طبيعة المنقول.
ويتم البيع بالمزاد العلني بالمناداة بشرط دفع الثمن فورا، ويجب عدم البدء في البيع إلا بعد أن يتم جرد المنقولات محل البيع وتحرير محضر بذلك.
ويشتمل محضر البيع على ذكر جميع إجراءات البيع وما تم من الاعتراضات والعقبات وما اتخذ في شأنها وحضور الدائن أو مقدم الضمان أو غيابه والثمن الذي رسا به المزاد وعلى اسم من رسا عليه وتوقيعه.
وإذا لم يدفع المشتري الثمن فورا وجبت إعادة البيع وفقا للإجراءات السابقة.
ويكون للمدين ومقدم الضمان وأي من أصحاب الحقوق الأخرى على المنقول أن يتقدم لقاضي الأمور المستعجلة بالمحكمة المختصة لإيقاف إجراءات البيع قبل يوم عمل على الأقل من التاريخ المحدد لبيع المنقول على أن يرفق بالطلب ما يفيد إيداع خزينة المحكمة ما يكفي لسداد حقوق الدائنين المشهرة بالسجل أو المتبقي منها بحسب الأحوال بالإضافة إلى جميع المصاريف والنفقات، ويترتب على قبول الطلب وقف إجراءات البيع
ويتم سداد حقوق الدائنين بحسب ترتيبها وكذلك مصاريف ونفقات التنفيذ من المبالغ المودعة خزينة المحكمة.
ولقاضي التنفيذ بناء على طلب المدين أو مقدم الضمان أو أي من أصحاب الحقوق الأخرى على المنقول الضامن أن يعدل في إجراءات التنفيذ في أية مرحلة من مراحلها بالشكل الذي يراه مناسبا إذا تبين وقوع مخالفة لإجراءات التنفيذ على المنقول الضامن والمنصوص عليها في القانون وهذه اللائحة.$m246$,'26a1d3f70d57a4d7d92c727cad4a6863',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(40,0,1,$m246$يجب مراعاة الإجراءات الآتية في حالة بيع المنقول الضامن من الدائن:
1- أن يودع حصيلة البيع خزينة المحكمة الاقتصادية المختصة الواقع في دائرتها موطن المدين.
2- أن يسلم قلم كتاب المحكمة بيانا بالحقوق على المنقول الضامن المشهرة في السجل كما هي في اليوم السابق بتاريخ إيداع حصيلة البيع.$m246$,'432aebe76254bab96e0d553c3bf7172e',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(41,0,1,$m246$يأمر القاضي المختص بالمحكمة الاقتصادية بإعداد قائمة توزيع مؤقتة للعوائد وحصيلة التنفيذ وفقا للأولويات المحددة في المادة (25) من القانون وتبليغها لطالب التنفيذ وأصحاب الحقوق الأخرى على المنقول الضامن المشهرة في السجل كما هي في اليوم السابق لتاريخ إيداع حصيلة البيع.
وللأشخاص المشار إليهم في الفقرة السابقة حق الاعتراض كتابة على القائمة المؤقتة خلال خمسة أيام من تاريخ تبليغهم، على أن يفصل القاضي المختص بالمحكمة الاقتصادية في الاعتراضات بصفة الاستعجال ويصدر قرارا بالقائمة النهائية للتوزيع.
وتتولى إدارة التنفيذ توزيع العوائد وحصيلة التنفيذ خلال سبعة أيام من تاريخ قرار القاضي المختص بالمحكمة الاقتصادية.
وترد للمدين أو مقدم الضمان بحسب الأحوال أي فوائض من حصيلة التنفيذ تزيد على الوفاء بحقوق الدائنين.$m246$,'0b55f8f712df6adb4f7a8443007e4adb',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(42,0,1,$m246$إذا كانت حصيلة بيع المنقول الضامن والعوائد الناتجة عنه المنصوص عليها بالمادة (18) من القانون لا تكفي للوفاء بالتزامات وحقوق الدائنين المشهرة بالسجل فتوزع وفق الترتيب الآتي:
1- نفقات إصلاح المنقول الضامن وصيانته وإعداده للبيع.
2- رسوم ونفقات التنفيذ على المنقول الضامن.
3- سداد مستحقات أصحاب حقوق الضمان المشهرة على المنقول الضامن حسب أولويتها وفقا لأحكام هذا القانون.
4- سداد مستحقات أصحاب حقوق الامتياز وغيرها من الحقوق المقررة وفقا لأولويتها طبقا للقوانين المنظمة لها. ويكون لكل دائن مطالبة المدين بالباقي من قيمة الدين وعوائده وفقا للقواعد العامة المقررة في القانون لاستئداء الديون.$m246$,'7ccf3d1eef2cbeea0d57fb7b93f61618',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$),
(43,0,1,$m246$يجوز للمدين التصرف في المنقول أو تأجيره بعد سداد الدين المضمون أو بالباقي منه بحسب الأحوال وبعد خصم مقابل تعجيل الوفاء المتفق عليه في عقد الضمان، وذلك بعد حصوله على صورة من البيانات المشهرة بالسجل والتي تفيد شطب الشهر المقيد على حق الضمان المشهر أو إلغاءه سواء للوفاء بالدين المضمون في الميعاد المحدد له بمدة سريان الإشهار، أو حال القيام بالسداد المعجل أو بانقضاء حق الضمان لأي سبب.
ويجوز للمدين بيع المنقول أو تأجيره إلى شخص آخر محملا بحق الضمان ويكون المدين الأصلي ضامنا للمشتري أو المستأجر في تنفيذ التزاماته الناشئة عن عقد الضمان.$m246$,'b5ba95a0a54853c10a2c8769995ee42a',DATE '2016-12-16',NULL,'active',NULL,NULL,$m246$النص كما طُبع بالمصدر، تاريخ العمل به (2016-12-16) محسوب: اليوم التالى لنشر القرار باللائحة فى الوقائع المصرية بتاريخ 2016-12-15 بحسب مصدر ثانوى هو موقع منشورات (مادة الإصدار 2). لا علامة تعديل على هذه المادة بالمصدر.$m246$);

DO $m246$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m246_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m246_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[246] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m246_art) <> 45 OR (SELECT sum(char_length(body)) FROM m246_art) <> 34605 OR (SELECT count(*) FROM m246_ver) <> 48 THEN
    RAISE EXCEPTION '[246] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=108 AND law_year=2016 AND kind='regulation';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الضمانات المنقولة%' THEN
    RAISE EXCEPTION '[246] يوجد مستند آخر برقم 108 لسنة 2016 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (108, 2016, $t246$اللائحة التنفيذية لقانون تنظيم الضمانات المنقولة الصادر بالقانون رقم 115 لسنة 2015 بقرار وزير الاستثمار رقم 108 لسنة 2016 (النسخة المحدثة بعد تعديلها بقرار رئيس مجلس الوزراء رقم 908 لسنة 2020)$t246$, $t246$اللائحة التنفيذية لقانون الضمانات المنقولة 108/2016$t246$, 'other', 'amended', NULL, DATE '2016-12-15', DATE '2020-04-16', 'EG', 'regulation', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m246_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m246_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m246_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 45 THEN
    RAISE EXCEPTION '[246] عدد صفوف النص % بدل 45', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 48 THEN
    RAISE EXCEPTION '[246] عدد نسخ النص % بدل 48', v_vcnt;
  END IF;
  RAISE NOTICE '[246] لائحة 108/2016: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m246$;
